function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return defaultState();
    const d = defaultState();
    const p = JSON.parse(raw);
    const merged = Object.assign(d, p);
    merged.upgrades = Object.assign({ engine: 1, handling: 1, aero: 1 }, p.upgrades || {});
    merged.story = Object.assign(d.story, p.story || {});
    merged.story.guards = Object.assign({ 1: 0, 2: 0, 3: 0, 4: 0 }, (p.story || {}).guards || {});
    if (!Array.isArray(merged.trackGrid) || merged.trackGrid.length !== 5) merged.trackGrid = makeSampleOval();
    if (!Array.isArray(merged.ownedModels) || !merged.ownedModels.length) merged.ownedModels = ['coupe'];
    if (!Array.isArray(merged.tracks)) merged.tracks = [];
    if (!Array.isArray(merged.garage)) merged.garage = [];
    merged.cash = Math.max(0, Number(merged.cash) || 0);
    return merged;
  } catch (e) {
    console.warn('save load failed', e);
    return defaultState();
  }
}

let saveTimer = null;
function save(immediate = false) {
  const write = () => {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(S)); } catch (e) { console.warn('save failed', e); }
