function toast(msg, kind = 'info') {
  const wrap = $('#toasts');
  if (!wrap) return;
  const el = document.createElement('div');
  const colors = kind === 'good' ? 'border-lime/40 text-lime bg-[#0d1408]/95' : kind === 'bad' ? 'border-rose-400/40 text-rose-300 bg-[#190b0f]/95' : kind === 'key' ? 'border-sky-400/40 text-sky-300 bg-[#08131c]/95' : 'border-white/15 text-slate-200 bg-[#0b0e16]/95';
  el.className = `toast pointer-events-none w-full rounded-xl border px-3 py-2 text-center text-[11.5px] font-semibold shadow-lg backdrop-blur ${colors}`;
  el.textContent = msg;
  wrap.appendChild(el);
  setTimeout(() => { el.style.transition = 'opacity .3s, transform .3s'; el.style.opacity = '0'; el.style.transform = 'translateY(-8px)'; }, 2200);
  setTimeout(() => el.remove(), 2600);
  while (wrap.children.length > 3) wrap.firstChild.remove();
}

function modal(title, body, okText, onOk, cancelText = 'Cancel') {
