/* ---------------- AUDIO ---------------- */
const Sfx = {
  ctx: null,
  master: null,
  init() {
    if (this.ctx) return;
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.16;
      this.master.connect(this.ctx.destination);
    } catch (e) { console.warn('audio unavailable', e); }
  },
  resume() { this.init(); if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume(); },
  tone(freq, dur, type = 'sine', gain = .5, slideTo = null, delay = 0) {
    if (!S.sound) return;
    this.resume();
    if (!this.ctx) return;
    const t0 = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t0);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(30, slideTo), t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    o.connect(g); g.connect(this.master);
    o.start(t0); o.stop(t0 + dur + .02);
  },
  noise(dur, gain = .4, freq = 800, q = 1) {
    if (!S.sound) return;
    this.resume(); if (!this.ctx) return;
    const t0 = this.ctx.currentTime;
    const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = this.ctx.createBufferSource(); src.buffer = buf;
    const f = this.ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = freq; f.Q.value = q;
    const g = this.ctx.createGain(); g.gain.value = gain;
    src.connect(f); f.connect(g); g.connect(this.master); src.start(t0);
  },
  unlock() { this.tone(523, .18, 'triangle', .5); this.tone(784, .22, 'triangle', .45, null, .09); this.tone(1046, .3, 'triangle', .35, null, .18); },
  jump() { this.tone(180, .28, 'sawtooth', .16, 640); },
  bump() { this.noise(.12, .5, 260, .8); this.tone(70, .12, 'square', .18, 45); },
  lap() { this.tone(880, .12, 'sine', .4); this.tone(1174, .18, 'sine', .32, null, .08); },
  win() { [523, 659, 784, 1046].forEach((f, i) => this.tone(f, .3, 'triangle', .4, null, i * .1)); },
  lose() { this.tone(330, .25, 'sawtooth', .2, 220); this.tone(220, .4, 'sawtooth', .18, 120, .12); },
  coin() { this.tone(1320, .08, 'square', .18); this.tone(1760, .12, 'square', .14, null, .05); },
  key() { [659, 880, 1175, 1568].forEach((f, i) => this.tone(f, .22, 'sine', .3, null, i * .07)); },
  boost() { this.tone(300, .4, 'sawtooth', .14, 900); },
  click() { this.tone(520, .05, 'sine', .16); },
};

