  $$('[data-tab]').forEach(btn => btn.classList.toggle('active', btn.dataset.tab === tab));
  $$('[data-tab-jump]').forEach(btn => btn.classList.toggle('active', btn.dataset.tabJump === tab));
  if (tab === 'customize') { showroom.resize(); showroom.renderAll(); }
  if (tab === 'track') { renderTrackBuilder(); renderSavedTracks(); }
  if (tab === 'story') { renderStoryPage(); }
  window.scrollTo({ top: 0, behavior: 'smooth' });
  Sfx.resume();
}
