/* ---------------- LOADOUT STATS ---------------- */
function loadoutStats() {
  const m = getModel(), w = getWheel();
  let speed = m.stats.speed, accel = m.stats.accel, grip = m.stats.grip;
  speed += (S.upgrades.engine - 1) * 0.6;
  grip += (S.upgrades.handling - 1) * 0.6;
  accel += (S.upgrades.aero - 1) * 0.4;
  speed += (S.upgrades.aero - 1) * 0.25;
  grip += w.grip * 0.5;
  for (const id of S.equippedParts) {
    const p = PARTS.find(p => p.id === id);
    if (!p) continue;
    if (p.effect.speed) speed += p.effect.speed * 0.45;
    if (p.effect.grip) grip += p.effect.grip * 0.45;
    if (p.effect.accel) accel += p.effect.accel * 0.45;
  }
  return { speed: clamp(speed, 1, 14), accel: clamp(accel, 1, 14), grip: clamp(grip, 1, 14) };
}
function starPct(v) { return clamp(v / 13 * 100, 8, 100); }

/* ---------------- CUSTOMIZE UI ---------------- */
function renderPaint() {
  const wrap = $('#paintSwatches');
  if (!wrap) return;
  wrap.innerHTML = PAINTS.map(p => `<button class="swatch ${S.paint === p.id ? 'active' : ''}" data-paint="${p.id}" title="${p.name}" style="background:linear-gradient(145deg,${p.css},${p.css}cc)"><span class="absolute inset-0 rounded-full" style="background:radial-gradient(circle at 35% 28%,rgba(255,255,255,.5),transparent 45%)"></span></button>`).join('');
  $('#paintLabel').textContent = getPaint().name;
  $$('#paintSwatches [data-paint]').forEach(btn => btn.addEventListener('click', () => {
    S.paint = btn.dataset.paint; renderPaint(); save(); showroom.applyConfig(); Sfx.click();
  }));
}

function renderModels() {
  const grid = $('#modelGrid');
  if (!grid) return;
  grid.innerHTML = MODELS.map(m => {
    const owned = S.ownedModels.includes(m.id);
    const selected = S.model === m.id;
    const canKey = m.secret;
    const priceTxt = owned ? '' : (canKey ? `<div class="mt-0.5 flex items-center gap-1 text-[8.5px] text-sky-300"><span>🔹${m.keys}</span><span>+ $${m.price}</span></div>` : `<div class="mt-0.5 text-[8.5px] text-amber-300">$${m.price}</div>`);
    return `<button class="pick-card ${selected ? 'active' : ''} ${owned ? '' : 'locked'}" data-model="${m.id}">
      <div class="flex items-start justify-between gap-1">
        <span class="text-[17px] leading-none">${m.secret ? '🌟' : m.id === 'truck' ? '🛻' : m.id === 'formula' ? '🏎️' : m.id === 'van' ? '🚐' : m.id === 'buggy' ? '🛺' : m.id === 'muscle' ? '🚗' : m.id === 'wedge' ? '🔺' : '🚙'}</span>
        ${owned ? (selected ? '<span class="text-[8px] font-black text-lime">ON</span>' : '<span class="text-[8px] text-slate-500">✓</span>') : '<span class="text-[9px]">🔒</span>'}
      </div>
      <div class="mt-1 text-[10px] font-bold leading-tight ${selected ? 'text-lime' : 'text-slate-200'}">${m.name}</div>
      ${priceTxt}
      ${m.secret ? '<div class="tag secret mt-1 inline-block">Secret</div>' : ''}
    </button>`;
  }).join('');
  $('#modelCount').textContent = `${S.ownedModels.length} / ${MODELS.length}`;
  $('#modelBadge').textContent = getModel().name;
  $$('#modelGrid [data-model]').forEach(btn => btn.addEventListener('click', () => selectModel(btn.dataset.model)));
}

function selectModel(id) {
  const m = MODELS.find(x => x.id === id);
  if (!m) return;
  if (S.ownedModels.includes(id)) {
    S.model = id; renderModels(); updateStatsUI(); save(); showroom.applyConfig(); Sfx.click();
    toast(`${m.name} selected`, 'good');
    return;
  }
  if (m.secret) {
    if (S.blueKeys < m.keys) { toast(`Need ${m.keys} Blue Keys`, 'bad'); Sfx.bump(); return; }
    if (S.cash < m.price) { toast(`Need $${m.price} more cash`, 'bad'); Sfx.bump(); return; }
    modal('Unlock Secret Car', `<b class="text-amber-300">${m.name}</b><br><span class="text-slate-400">${m.desc}</span><br><br>Cost: <b class="text-sky-300">🔹 ${m.keys} Blue Keys</b> + <b class="text-amber-300">$${m.price}</b>`, 'Unlock', () => {
      S.blueKeys -= m.keys; S.cash -= m.price; S.ownedModels.push(id); S.model = id;
      Sfx.unlock(); toast(`🌟 ${m.name} unlocked!`, 'key'); renderModels(); updateStatsUI(); save(true); showroom.applyConfig(); renderCurrencyCompact();
    });
  } else {
    if (S.cash < m.price) { toast(`Need $${m.price} — win a few races`, 'bad'); Sfx.bump(); return; }
    modal('Buy ' + m.name, `<span class="text-slate-400">${m.desc}</span><br><br>Price: <b class="text-amber-300">$${m.price}</b>`, 'Buy', () => {
      S.cash -= m.price; S.ownedModels.push(id); S.model = id;
      Sfx.unlock(); toast(`${m.name} purchased`, 'good'); renderModels(); updateStatsUI(); save(true); showroom.applyConfig();
    });
  }
}

function renderWheels() {
  const grid = $('#wheelGrid');
  if (!grid) return;
  grid.innerHTML = WHEELS.map(w => {
    const owned = S.ownedWheels.includes(w.id);
    const sel = S.wheels === w.id;
    return `<button class="pick-card ${sel ? 'active' : ''} ${owned ? '' : 'locked'}" data-wheel="${w.id}">
      <div class="flex items-center justify-between"><span class="text-[17px]">${w.id === 'offroad' ? '⚙️' : w.id === 'sport' ? '🛞' : '⭕'}</span>${owned ? (sel ? '<span class="text-[8px] font-black text-lime">ON</span>' : '') : '<span class="text-[9px]">🔒</span>'}</div>
      <div class="mt-1 text-[10px] font-bold ${sel ? 'text-lime' : 'text-slate-200'}">${w.name}</div>
      <div class="text-[8.5px] ${owned ? 'text-slate-500' : 'text-amber-300'}">${owned ? (w.grip ? `+${w.grip} grip` : 'stock') : '$' + w.price}</div>
    </button>`;
  }).join('');
  $$('#wheelGrid [data-wheel]').forEach(btn => btn.addEventListener('click', () => {
    const w = WHEELS.find(x => x.id === btn.dataset.wheel);
    if (S.ownedWheels.includes(w.id)) { S.wheels = w.id; renderWheels(); updateStatsUI(); save(); showroom.applyConfig(); Sfx.click(); return; }
    if (S.cash < w.price) { toast(`Need $${w.price}`, 'bad'); Sfx.bump(); return; }
    modal('Buy ' + w.name + ' Wheels', `+${w.grip} grip. Price: <b class="text-amber-300">$${w.price}</b>`, 'Buy', () => {
      S.cash -= w.price; S.ownedWheels.push(w.id); S.wheels = w.id; Sfx.unlock(); toast(`${w.name} wheels equipped`, 'good');
      renderWheels(); updateStatsUI(); save(true); showroom.applyConfig();
    });
  }));
}

function renderParts() {
  const grid = $('#partGrid');
  if (!grid) return;
  grid.innerHTML = PARTS.map(p => {
    const owned = hasPart(p.id); const eq = partEquipped(p.id);
    const action = owned ? (eq ? 'Equipped' : 'Equip') : `$${p.price}`;
    return `<button class="pick-card ${eq ? 'active' : ''} ${owned ? '' : 'locked'}" data-part="${p.id}">
      <div class="flex items-start justify-between">
        <span class="text-[16px] leading-none">${owned ? p.icon : '🔒'}</span>
        <span class="tag ${p.type === 'cos' ? 'cos' : 'race'}">${p.type === 'cos' ? 'Cos' : 'Race'}</span>
      </div>
      <div class="mt-1 text-[10px] font-bold leading-tight ${eq ? 'text-lime' : 'text-slate-200'}">${owned ? p.name : (p.type === 'cos' ? 'Locked Cosmetic' : 'Locked Race Tool')}</div>
      <div class="mt-0.5 flex items-center justify-between text-[8.5px]">
        <span class="${owned ? 'text-slate-500' : 'text-amber-300'}">${owned ? (p.effect.speed ? '+speed' : p.effect.grip ? '+grip' : p.effect.magnet ? '+coins' : p.effect.collision ? '+armor' : 'cosmetic') : '$' + p.price}</span>
        <span class="${eq ? 'text-lime font-bold' : owned ? 'text-slate-400' : 'text-slate-500'}">${action}</span>
      </div>
    </button>`;
  }).join('');
  $$('#partGrid [data-part]').forEach(btn => btn.addEventListener('click', () => clickPart(btn.dataset.part)));
}

function clickPart(id) {
  const p = PARTS.find(x => x.id === id);
  if (!p) return;
  if (hasPart(id)) {
    if (partEquipped(id)) { S.equippedParts = S.equippedParts.filter(x => x !== id); }
    else {
      // mutually exclusive cosmetics for a clean look; race tools stack
      if (p.type === 'cos') S.equippedParts = S.equippedParts.filter(x => (PARTS.find(q => q.id === x) || {}).type !== 'cos');
      S.equippedParts.push(id);
    }
    Sfx.click(); renderParts(); updateStatsUI(); save(); showroom.applyConfig();
    return;
  }
  if (S.cash < p.price) { toast(`Need $${p.price} — race for cash & drops`, 'bad'); Sfx.bump(); return; }
  modal('Unlock ' + p.name, `<span class="text-slate-400">${p.desc}</span><br><br>Price: <b class="text-amber-300">$${p.price}</b><br><span class="text-[10px] text-slate-500">Also available as a 1-in-6 drop when you win races.</span>`, 'Unlock', () => {
    S.cash -= p.price; S.ownedParts.push(id);
    if (p.type === 'cos') S.equippedParts = S.equippedParts.filter(x => (PARTS.find(q => q.id === x) || {}).type !== 'cos');
    S.equippedParts.push(id);
    Sfx.unlock(); toast(`${p.name} unlocked`, 'key'); renderParts(); updateStatsUI(); save(true); showroom.applyConfig();
  });
}

function renderUpgrades() {
  const wrap = $('#upgradeRows');
  if (!wrap) return;
  const defs = [
    { key: 'engine', name: 'Engine', icon: '⚙️', desc: 'Top speed' },
    { key: 'handling', name: 'Handling', icon: '🎯', desc: 'Cornering grip' },
    { key: 'aero', name: 'Aero', icon: '🌪️', desc: 'Accel & top end' },
  ];
  wrap.innerHTML = defs.map(d => {
    const lv = S.upgrades[d.key]; const max = lv >= 5;
    return `<div class="rounded-xl border border-white/[.07] bg-white/[.025] p-2.5">
      <div class="flex items-center justify-between">
        <div class="flex items-center gap-1.5"><span class="text-sm">${d.icon}</span><div><div class="text-[11px] font-bold text-slate-100">${d.name}</div><div class="text-[8.5px] uppercase tracking-wider text-slate-500">${d.desc}</div></div></div>
        <span class="text-[9px] font-black ${max ? 'text-lime' : 'text-slate-400'}">${max ? 'MAX' : 'Lv.' + lv}</span>
      </div>
      <div class="mt-2 flex gap-1">${[1,2,3,4,5].map(i => `<div class="h-1.5 flex-1 rounded-full ${i <= lv ? 'bg-lime' : 'bg-white/10'}"></div>`).join('')}</div>
      <button class="btn small w-full mt-2 ${max ? '' : 'primary'}" data-upg="${d.key}" ${max ? 'disabled' : ''}>${max ? 'Maxed' : `Upgrade · $100`}</button>
    </div>`;
  }).join('');
  $$('#upgradeRows [data-upg]').forEach(btn => btn.addEventListener('click', () => {
    const k = btn.dataset.upg;
    if (S.upgrades[k] >= 5) return;
    if (S.cash < 100) { toast('Need $100', 'bad'); Sfx.bump(); return; }
    S.cash -= 100; S.upgrades[k]++; Sfx.unlock(); toast(`${k[0].toUpperCase() + k.slice(1)} → Lv.${S.upgrades[k]}`, 'good');
    renderUpgrades(); updateStatsUI(); save(true); showroom.applyConfig();
  }));
}

function updateStatsUI() {
  const st = loadoutStats();
  const set = (id, v) => { const el = $(id); if (el) el.style.width = starPct(v) + '%'; };
  set('#statSpeed', st.speed); set('#statAccel', st.accel); set('#statGrip', st.grip);
  const txt = (id, v) => { const el = $(id); if (el) el.textContent = (v / 1.3).toFixed(1); };
  txt('#statSpeedTxt', st.speed); txt('#statAccelTxt', st.accel); txt('#statGripTxt', st.grip);
  $('#modelBadge').textContent = getModel().name;
}

function renderGarage() {
  const wrap = $('#garageList');
  if (!wrap) return;
  if (!S.garage.length) {
    wrap.innerHTML = `<div class="col-span-full rounded-xl border border-dashed border-white/10 p-3 text-center text-[10.5px] text-slate-500">No saved builds yet. Tune your RC and hit <b class="text-slate-300">Save Build</b>.</div>`;
    return;
  }
  wrap.innerHTML = S.garage.map((g, i) => {
    const p = PAINTS.find(x => x.id === g.paint) || PAINTS[0];
    const m = MODELS.find(x => x.id === g.model) || MODELS[0];
    return `<div class="flex items-center gap-2 rounded-xl border border-white/[.07] bg-white/[.025] p-2">
      <div class="h-7 w-7 shrink-0 rounded-full border border-white/20" style="background:${p.css}"></div>
      <div class="min-w-0 flex-1"><div class="truncate text-[10.5px] font-bold text-slate-100">${escapeHtml(g.name)}</div><div class="text-[8.5px] text-slate-500">${m.name} · E${g.upgrades?.engine || 1} H${g.upgrades?.handling || 1} A${g.upgrades?.aero || 1}</div></div>
      <button class="btn small !px-2" data-loadbuild="${i}" title="Load">↺</button>
      <button class="btn small danger !px-2" data-delbuild="${i}" title="Delete">✕</button>
    </div>`;
  }).join('');
  $$('#garageList [data-loadbuild]').forEach(b => b.addEventListener('click', () => loadBuild(+b.dataset.loadbuild)));
  $$('#garageList [data-delbuild]').forEach(b => b.addEventListener('click', () => {
    const i = +b.dataset.delbuild;
    S.garage.splice(i, 1); save(true); renderGarage(); toast('Build deleted');
  }));
}
function escapeHtml(s) { return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }

$('#saveBuildBtn').addEventListener('click', () => {
  const name = ($('#garageName').value || '').trim() || `Build ${S.garage.length + 1}`;
  if (S.garage.length >= 8) { toast('Garage full — delete a build first', 'bad'); return; }
  S.garage.push({ name, paint: S.paint, model: S.model, wheels: S.wheels, parts: [...S.equippedParts], upgrades: { ...S.upgrades } });
  $('#garageName').value = '';
  save(true); renderGarage(); Sfx.unlock(); toast(`Saved “${name}”`, 'good');
});
$('#garageName').addEventListener('input', () => {});
$('#randomizeBtn').addEventListener('click', () => {
  S.paint = pick(PAINTS).id;
  S.model = pick(S.ownedModels);
  S.wheels = pick(S.ownedWheels);
  const owned = PARTS.filter(p => hasPart(p.id));
  S.equippedParts = [];
  const cos = pick(owned.filter(p => p.type === 'cos'));
  if (cos) S.equippedParts.push(cos.id);
  for (const p of owned.filter(p => p.type === 'race')) if (Math.random() < .55) S.equippedParts.push(p.id);
  Sfx.click(); renderPaint(); renderModels(); renderWheels(); renderParts(); updateStatsUI(); save(); showroom.applyConfig();
  toast('Randomized build', 'good');
});
$('#resetBuildBtn').addEventListener('click', () => {
  S.paint = 'red'; S.model = 'coupe'; S.wheels = 'classic'; S.equippedParts = []; S.upgrades = { engine: 1, handling: 1, aero: 1 };
  Sfx.click(); renderPaint(); renderModels(); renderWheels(); renderParts(); renderUpgrades(); updateStatsUI(); save(); showroom.applyConfig();
  toast('Build reset');
});
function loadBuild(i) {
  const g = S.garage[i]; if (!g) return;
  S.paint = g.paint; S.model = g.model; S.wheels = g.wheels; S.equippedParts = [...(g.parts || [])];
  S.upgrades = Object.assign({ engine: 1, handling: 1, aero: 1 }, g.upgrades || {});
  Sfx.click(); renderPaint(); renderModels(); renderWheels(); renderParts(); renderUpgrades(); updateStatsUI(); save(); showroom.applyConfig();
  toast(`Loaded “${escapeHtml(g.name)}”`, 'good');
}

function renderTrackQuickList() {
  const wrap = $('#trackQuickList');
  if (!wrap) return;
  if (!S.tracks.length) {
    wrap.innerHTML = `<div class="rounded-xl border border-dashed border-white/10 p-3 text-center text-[10.5px] text-slate-500">No saved tracks yet.</div>`;
    return;
  }
  wrap.innerHTML = S.tracks.map((t, i) => `<button class="flex items-center gap-2 rounded-xl border border-white/[.07] bg-white/[.025] p-2 text-left hover:bg-white/[.06]" data-loadtrackquick="${i}">
    <span class="grid h-7 w-9 place-items-center rounded-md border border-white/10 text-[9px] font-bold" style="background:${terrainCss(t.terrain)}">🏁</span>
    <span class="min-w-0 flex-1"><span class="block truncate text-[10.5px] font-bold text-slate-100">${escapeHtml(t.name)}</span><span class="block text-[8.5px] text-slate-500">${terrainName(t.terrain)} · ${t.tiles || 0} tiles</span></span>
    <span class="text-[9px] text-slate-500">Load</span>
  </button>`).join('');
  $$('#trackQuickList [data-loadtrackquick]').forEach(b => b.addEventListener('click', () => {
    const t = S.tracks[+b.dataset.loadtrackquick]; if (!t) return;
    S.trackGrid = JSON.parse(JSON.stringify(t.grid)); S.terrain = t.terrain; S.time = t.time; S.lastTrackName = t.name;
    save(); setTab('track'); toast(`Loaded “${escapeHtml(t.name)}”`, 'good');
  }));
}
function terrainCss(id) { const t = TERRAINS.find(x => x.id === id) || TERRAINS[0]; return t.bg; }
function terrainName(id) { const t = TERRAINS.find(x => x.id === id) || TERRAINS[0]; return t.name; }

function renderCurrencyCompact() { updateCurrencyHud(); }

