+  { id: 'shocks',  name: 'Shock Absorbers', price: 500, icon: '🔧', type: 'race', effect: { grip: 1, stability: 1 }, desc: 'Soak up bumps and landings.' },
+  { id: 'bumper',  name: 'Heavy Bumper',    price: 550, icon: '🛡️', type: 'race', effect: { collision: 1 },        desc: 'Shrug off car-to-car hits.' },
+  { id: 'magnet',  name: 'Lucky Magnet',    price: 600, icon: '🧲', type: 'race', effect: { magnet: 1 },           desc: 'Pulls bonus coins closer.' },
