/* ============================================================
   THREE.JS — CAR BUILDER + SHOWROOM
   ============================================================ */
let ENV_TEXTURE = null;

function makeRoundedBoxGeo(w, h, d, r = .12, curveSeg = 5) {
  r = Math.min(r, Math.min(w, d) / 2 - .001);
  const shape = new THREE.Shape();
  const x = -w / 2, y = -d / 2;
  shape.moveTo(x + r, y);
  shape.lineTo(x + w - r, y); shape.quadraticCurveTo(x + w, y, x + w, y + r);
  shape.lineTo(x + w, y + d - r); shape.quadraticCurveTo(x + w, y + d, x + w - r, y + d);
  shape.lineTo(x + r, y + d); shape.quadraticCurveTo(x, y + d, x, y + d - r);
  shape.lineTo(x, y + r); shape.quadraticCurveTo(x, y, x + r, y);
  const geo = new THREE.ExtrudeGeometry(shape, { depth: h, bevelEnabled: true, bevelSize: .025, bevelThickness: .025, bevelSegments: 2, curveSegments: curveSeg });
  geo.rotateX(-Math.PI / 2);
  geo.center();
  return geo;
}
function shadowTexture() {
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 4, 64, 64, 62);
  g.addColorStop(0, 'rgba(0,0,0,.72)'); g.addColorStop(.5, 'rgba(0,0,0,.34)'); g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 128, 128);
  const tex = new THREE.CanvasTexture(c);
  return tex;
}
let CONTACT_SHADOW = null;
function getContactShadow() {
  if (!CONTACT_SHADOW) CONTACT_SHADOW = shadowTexture();
  return CONTACT_SHADOW;
}

function getEquippedPart(id) { return partEquipped(id); }

function carSpec(id) {
  const specs = {
    coupe:   { len: 3.9, wid: 1.82, bodyH: .46, bodyY: .48, cabW: 1.48, cabH: .50, cabL: 1.62, cabZ: -.18, wheelR: .35, wheelW: .27, wb: 2.46, track: 1.58 },
    truck:   { len: 4.35, wid: 2.02, bodyH: .56, bodyY: .55, cabW: 1.68, cabH: .72, cabL: 1.38, cabZ: .72, wheelR: .44, wheelW: .34, wb: 2.7, track: 1.75 },
    formula: { len: 4.5, wid: 1.7, bodyH: .34, bodyY: .42, cabW: 1.05, cabH: .38, cabL: .95, cabZ: -.15, wheelR: .37, wheelW: .32, wb: 2.95, track: 1.85 },
    van:     { len: 4.3, wid: 2.02, bodyH: .62, bodyY: .58, cabW: 1.84, cabH: .95, cabL: 2.85, cabZ: -.25, wheelR: .38, wheelW: .28, wb: 2.72, track: 1.7 },
    buggy:   { len: 4.05, wid: 1.9, bodyH: .4, bodyY: .66, cabW: 1.3, cabH: .42, cabL: 1.3, cabZ: -.2, wheelR: .5, wheelW: .38, wb: 2.55, track: 1.8 },
    wedge:   { len: 4.25, wid: 1.95, bodyH: .4, bodyY: .44, cabW: 1.35, cabH: .4, cabL: 1.35, cabZ: -.55, wheelR: .36, wheelW: .3, wb: 2.7, track: 1.68 },
    muscle:  { len: 4.35, wid: 2.0, bodyH: .5, bodyY: .5, cabW: 1.5, cabH: .46, cabL: 1.62, cabZ: -.2, wheelR: .39, wheelW: .34, wb: 2.7, track: 1.72 },
    specter: { len: 4.45, wid: 1.96, bodyH: .36, bodyY: .44, cabW: 1.35, cabH: .38, cabL: 1.55, cabZ: -.3, wheelR: .37, wheelW: .32, wb: 2.82, track: 1.74 },
    phantom: { len: 4.6, wid: 2.0, bodyH: .34, bodyY: .42, cabW: 1.3, cabH: .36, cabL: 1.35, cabZ: -.05, wheelR: .38, wheelW: .33, wb: 2.9, track: 1.76 },
  };
  return specs[id] || specs.coupe;
}

function buildCar(cfg, opts = {}) {
  const { paint = 'red', model = 'coupe', wheels = 'classic', parts = [], race = false } = cfg;
  const paintDef = PAINTS.find(p => p.id === paint) || PAINTS[0];
  const spec = carSpec(model);
  const wheelDef = WHEELS.find(w => w.id === wheels) || WHEELS[0];
  const group = new THREE.Group();
  const body = new THREE.Group();
  group.add(body);
  group.userData.disposables = [];
  const reg = (geo) => { group.userData.disposables.push(geo); return geo; };

  const paintMat = new THREE.MeshPhysicalMaterial({
    color: paintDef.hex, metalness: .35, roughness: .2, clearcoat: 1, clearcoatRoughness: .055,
    envMapIntensity: 1.5, reflectivity: 1
  });
  const darkMat = new THREE.MeshPhysicalMaterial({ color: 0x0b0d12, metalness: .55, roughness: .35, clearcoat: .7, clearcoatRoughness: .2, envMapIntensity: .9 });
  const rubberMat = new THREE.MeshStandardMaterial({ color: 0x0f1012, roughness: .88, metalness: .02 });
  const rimMat = new THREE.MeshPhysicalMaterial({ color: wheelDef.rim, metalness: .95, roughness: .18, clearcoat: 1, envMapIntensity: 1.2 });
  const chromeMat = new THREE.MeshPhysicalMaterial({ color: 0xd9dee6, metalness: 1, roughness: .1, envMapIntensity: 1.4 });
  const glassTint = parts.includes('tint');
  const glassMat = new THREE.MeshPhysicalMaterial({
    color: glassTint ? 0x05070a : 0x213244, metalness: .2, roughness: .05,
    transparent: true, opacity: glassTint ? .96 : .62, clearcoat: 1, clearcoatRoughness: .02, envMapIntensity: 1.6
