  const accent = new THREE.Color(paintDef.hex).offsetHSL(.0, .05, .18);

  const add = (geo, mat, x, y, z, parent = body) => {
    const m = new THREE.Mesh(reg(geo), mat);
    m.position.set(x, y, z);
    m.castShadow = true; m.receiveShadow = false;
    parent.add(m);
    return m;
