  const wid = spec.wid, len = spec.len;
  const wheelR = spec.wheelR * (wheels === 'offroad' ? 1.12 : 1);
  const wheelW = spec.wheelW * (wheels === 'offroad' ? 1.28 : wheels === 'sport' ? 1.12 : 1);

  // ---------- body shapes per model ----------
  if (model === 'truck') {
    add(makeRoundedBoxGeo(wid, spec.bodyH, len, .18), paintMat, 0, spec.bodyY, 0);
    // bed walls
    add(makeRoundedBoxGeo(wid * .96, .3, 1.75, .08), paintMat, 0, spec.bodyY + .35, -1.05);
    add(makeRoundedBoxGeo(wid * .96, .3, .1, .04), paintMat, 0, spec.bodyY + .32, -1.95);
    // cabin front
    add(makeRoundedBoxGeo(spec.cabW, spec.cabH, spec.cabL, .14), paintMat, 0, spec.bodyY + spec.cabH * .6, spec.cabZ);
    add(makeRoundedBoxGeo(spec.cabW * .84, spec.cabH * .54, spec.cabL * .8, .08), glassMat, 0, spec.bodyY + spec.cabH * .72, spec.cabZ);
    // grille + lights
    add(new THREE.BoxGeometry(wid * .55, .16, .08), chromeMat, 0, spec.bodyY + .18, len / 2 + .01);
    add(new THREE.BoxGeometry(.34, .16, .1), headMat, -wid * .31, spec.bodyY + .38, len / 2 + .02);
    add(new THREE.BoxGeometry(.34, .16, .1), headMat, wid * .31, spec.bodyY + .38, len / 2 + .02);
    add(new THREE.BoxGeometry(wid * .8, .14, .08), tailMat, 0, spec.bodyY + .3, -len / 2 - .01);
  } else if (model === 'formula') {
    add(makeRoundedBoxGeo(wid * .42, .32, len * .92, .14), paintMat, 0, spec.bodyY, 0);
    add(makeRoundedBoxGeo(wid * .82, .22, 1.1, .1), paintMat, 0, spec.bodyY - .04, .75);
    // side pods
    add(makeRoundedBoxGeo(.42, .38, 1.7, .14), paintMat, -wid * .44, spec.bodyY, -.2);
    add(makeRoundedBoxGeo(.42, .38, 1.7, .14), paintMat, wid * .44, spec.bodyY, -.2);
    // cockpit
    add(makeRoundedBoxGeo(.78, spec.cabH, 1.0, .12), paintMat, 0, spec.bodyY + .24, spec.cabZ);
    add(makeRoundedBoxGeo(.66, .2, .8, .06), glassMat, 0, spec.bodyY + .38, spec.cabZ - .02);
    // rear wing
    add(new THREE.BoxGeometry(wid * 1.05, .06, .46), darkMat, 0, spec.bodyY + .78, -len / 2 + .18);
    add(new THREE.BoxGeometry(.06, .5, .3), chromeMat, -wid * .3, spec.bodyY + .55, -len / 2 + .18);
    add(new THREE.BoxGeometry(.06, .5, .3), chromeMat, wid * .3, spec.bodyY + .55, -len / 2 + .18);
    // front wing
    add(new THREE.BoxGeometry(wid * 1.2, .06, .5), paintMat, 0, spec.bodyY - .28, len / 2 - .05);
