    add(makeRoundedBoxGeo(spec.cabW * .88, spec.cabH * .42, .12, .05), glassMat, 0, spec.bodyY + spec.cabH * .74, -len / 2 - .01);
    add(makeRoundedBoxGeo(spec.cabW * .92, .42, spec.cabL * .62, .05), glassMat, 0, spec.bodyY + spec.cabH * .75, spec.cabZ + .2);
