    add(makeRoundedBoxGeo(.62, .5, .5, .1), darkMat, 0, spec.bodyY + .3, -.25);
    // roof light bar
    add(new THREE.BoxGeometry(wid * .55, .12, .16), headMat, 0, spec.bodyY + .86, -.7);
    add(makeRoundedBoxGeo(wid * .6, .26, .7, .1), paintMat, 0, spec.bodyY + .35, -1.15);
    add(new THREE.BoxGeometry(.3, .16, .1), headMat, -wid * .22, spec.bodyY + .16, len / 2 - .5);
    add(new THREE.BoxGeometry(.3, .16, .1), headMat, wid * .22, spec.bodyY + .16, len / 2 - .5);
  } else if (model === 'wedge') {
    add(makeRoundedBoxGeo(wid, spec.bodyH, len * .9, .2), paintMat, 0, spec.bodyY, 0);
    // sloped nose wedge using rotated box
    const nose = add(makeRoundedBoxGeo(wid * .9, .14, 1.6, .12), paintMat, 0, spec.bodyY + .16, len * .3);
    nose.rotation.x = -.16;
    // low canopy
    add(makeRoundedBoxGeo(spec.cabW, spec.cabH, spec.cabL, .26), paintMat, 0, spec.bodyY + .36, spec.cabZ);
    add(makeRoundedBoxGeo(spec.cabW * .82, spec.cabH * .52, spec.cabL * .74, .08), glassMat, 0, spec.bodyY + .46, spec.cabZ);
    // splitter
    add(new THREE.BoxGeometry(wid * 1.1, .055, .6), darkMat, 0, spec.bodyY - .22, len / 2 - .05);
    add(new THREE.BoxGeometry(wid * .92, .06, .4), darkMat, 0, spec.bodyY + .55, -len / 2 + .25);
    add(new THREE.BoxGeometry(.34, .12, .06), headMat, -wid * .3, spec.bodyY + .2, len / 2 + .01);
    add(new THREE.BoxGeometry(.34, .12, .06), headMat, wid * .3, spec.bodyY + .2, len / 2 + .01);
    add(new THREE.BoxGeometry(wid * .72, .12, .06), tailMat, 0, spec.bodyY + .34, -len / 2 - .01);
  } else if (model === 'muscle') {
    add(makeRoundedBoxGeo(wid, spec.bodyH, len, .22), paintMat, 0, spec.bodyY, 0);
    add(makeRoundedBoxGeo(wid * .95, .22, 1.3, .08), paintMat, 0, spec.bodyY + .3, 1.15);
    add(makeRoundedBoxGeo(spec.cabW, spec.cabH, spec.cabL, .16), paintMat, 0, spec.bodyY + .42, spec.cabZ);
    add(makeRoundedBoxGeo(spec.cabW * .84, spec.cabH * .5, spec.cabL * .82, .06), glassMat, 0, spec.bodyY + .52, spec.cabZ);
    // hood scoop
    add(makeRoundedBoxGeo(.56, .18, .8, .08), darkMat, 0, spec.bodyY + .42, 1.2);
    // side stripe
    for (const sx of [-1, 1]) add(new THREE.BoxGeometry(.02, .12, len * .8), new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: .5 }), sx * wid / 2, spec.bodyY + .12, 0);
    add(new THREE.BoxGeometry(.36, .18, .1), headMat, -wid * .3, spec.bodyY + .24, len / 2 + .01);
    add(new THREE.BoxGeometry(.36, .18, .1), headMat, wid * .3, spec.bodyY + .24, len / 2 + .01);
    add(new THREE.BoxGeometry(wid * .85, .18, .08), tailMat, 0, spec.bodyY + .28, -len / 2 - .01);
    add(new THREE.BoxGeometry(wid * .94, .06, .34), darkMat, 0, spec.bodyY + .62, -len / 2 + .2);
  } else {
    // coupe / specter / phantom
    const sleek = model === 'specter' || model === 'phantom';
    add(makeRoundedBoxGeo(wid, spec.bodyH, len, sleek ? .34 : .26), paintMat, 0, spec.bodyY, 0);
    // lower splitter
    add(makeRoundedBoxGeo(wid * .94, .18, len * .92, .1), darkMat, 0, spec.bodyY - .28, 0);
    // nose slope
    const nose = add(makeRoundedBoxGeo(wid * .94, .2, len * .42, .12), paintMat, 0, spec.bodyY + (sleek ? .14 : .2), len * .28);
    nose.rotation.x = sleek ? -.13 : -.06;
    // cabin
    add(makeRoundedBoxGeo(spec.cabW, spec.cabH, spec.cabL, .28), paintMat, 0, spec.bodyY + spec.cabH * .52, spec.cabZ);
    add(makeRoundedBoxGeo(spec.cabW * .86, spec.cabH * .56, spec.cabL * .82, .1), glassMat, 0, spec.bodyY + spec.cabH * .64, spec.cabZ);
    // rear deck
    add(makeRoundedBoxGeo(wid * .92, .18, 1.0, .1), paintMat, 0, spec.bodyY + .3, -len * .33);
    // lights
    add(new THREE.BoxGeometry(.4, .16, .08), headMat, -wid * .3, spec.bodyY + .18, len / 2 + .01);
    add(new THREE.BoxGeometry(.4, .16, .08), headMat, wid * .3, spec.bodyY + .18, len / 2 + .01);
    add(new THREE.BoxGeometry(wid * .74, .13, .06), tailMat, 0, spec.bodyY + .24, -len / 2 - .01);
    // side mirrors
    add(new THREE.BoxGeometry(.3, .1, .16), paintMat, -wid * .55, spec.bodyY + spec.cabH * .7, spec.cabZ + .5);
    add(new THREE.BoxGeometry(.3, .1, .16), paintMat, wid * .55, spec.bodyY + spec.cabH * .7, spec.cabZ + .5);
    if (sleek) {
      add(makeRoundedBoxGeo(wid * .9, .07, .42, .05), darkMat, 0, spec.bodyY + .62, -len / 2 + .14);
      add(new THREE.BoxGeometry(.05, .3, .26), chromeMat, -wid * .32, spec.bodyY + .47, -len / 2 + .14);
      add(new THREE.BoxGeometry(.05, .3, .26), chromeMat, wid * .32, spec.bodyY + .47, -len / 2 + .14);
      add(new THREE.BoxGeometry(.14, .1, .5), darkMat, 0, spec.bodyY + .1, -len / 2 - .06);
    }
  }

  // ---------- wheels ----------
  const wheelGroup = new THREE.Group();
  group.add(wheelGroup);
  const wheelPositions = [
    [-spec.track / 2, wheelR, spec.wb / 2], [spec.track / 2, wheelR, spec.wb / 2],
    [-spec.track / 2, wheelR, -spec.wb / 2], [spec.track / 2, wheelR, -spec.wb / 2],
  ];
  const tireGeo = new THREE.CylinderGeometry(wheelR, wheelR, wheelW, race ? 18 : 28, 1);
  const rimGeo = new THREE.CylinderGeometry(wheelR * .58, wheelR * .58, wheelW * 1.04, race ? 12 : 20, 1);
  const hubGeo = new THREE.CylinderGeometry(wheelR * .16, wheelR * .16, wheelW * 1.1, 8);
  const spokeGeo = new THREE.BoxGeometry(wheelR * .11, wheelR * .9, wheelW * .55);
  for (const [x, y, z] of wheelPositions) {
    const w = new THREE.Group();
    const tire = new THREE.Mesh(reg(tireGeo), rubberMat);
    tire.rotation.z = Math.PI / 2; tire.castShadow = true;
    const rim = new THREE.Mesh(reg(rimGeo), rimMat);
    rim.rotation.z = Math.PI / 2;
    w.add(tire, rim);
    for (let s = 0; s < 5; s++) {
      const sp = new THREE.Mesh(reg(spokeGeo), rimMat);
      sp.rotation.x = s * Math.PI / 5;
      sp.position.x = (x < 0 ? -1 : 1) * wheelW * .3;
      w.add(sp);
    }
    const hub = new THREE.Mesh(reg(hubGeo), chromeMat); hub.rotation.z = Math.PI / 2;
    w.add(hub);
    w.position.set(x, y, z);
    wheelGroup.add(w);
  }
  // fender arches offroad
  if (wheels === 'offroad') {
    for (const [x, , z] of wheelPositions) {
      const arch = add(new THREE.TorusGeometry(wheelR * 1.12, .045, 5, 12, Math.PI), darkMat, x, wheelR, z);
      arch.rotation.y = Math.PI / 2;
    }
  }

  // ---------- attachments ----------
  const rearZ = -len / 2;
  if (parts.includes('spoiler') && model !== 'formula' && model !== 'buggy') {
    add(new THREE.BoxGeometry(wid * .98, .055, .42), darkMat, 0, spec.bodyY + (model === 'van' ? 1.2 : .72), rearZ + .18);
    add(new THREE.BoxGeometry(.06, .34, .26), chromeMat, -wid * .34, spec.bodyY + (model === 'van' ? 1.0 : .54), rearZ + .18);
    add(new THREE.BoxGeometry(.06, .34, .26), chromeMat, wid * .34, spec.bodyY + (model === 'van' ? 1.0 : .54), rearZ + .18);
  }
  if (parts.includes('stripe')) {
    const stripeMat = new THREE.MeshStandardMaterial({ color: paintDef.id === 'white' || paintDef.id === 'yellow' ? 0x15181f : 0xf7f9fc, roughness: .35, metalness: .1 });
    add(new THREE.BoxGeometry(.3, .012, len * .82), stripeMat, 0, spec.bodyY + spec.bodyH / 2 + .02, 0);
    const s2 = add(new THREE.BoxGeometry(.3, .012, spec.cabL * .8), stripeMat, 0, spec.bodyY + spec.cabH * .9, spec.cabZ);
    s2.position.y += .02;
  }
  if (parts.includes('scoop')) {
    add(makeRoundedBoxGeo(.72, .2, .9, .08), paintMat, 0, spec.bodyY + spec.cabH * .92 + .1, spec.cabZ - .1);
    add(new THREE.BoxGeometry(.5, .08, .06), darkMat, 0, spec.bodyY + spec.cabH * .92 + .1, spec.cabZ + .36);
  }
  if (parts.includes('underglow')) {
    const glowMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(paintDef.hex).offsetHSL(.5, .4, .1), transparent: true, opacity: .55, blending: THREE.AdditiveBlending, depthWrite: false });
    const plane = add(new THREE.PlaneGeometry(wid * 1.3, len * .92), glowMat, 0, .045, 0);
    plane.rotation.x = -Math.PI / 2;
    const l = new THREE.PointLight(0x39e7ff, race ? .5 : 1.0, 5);
    l.position.set(0, .25, 0); group.add(l);
  }
  if (parts.includes('turbo')) {
    add(new THREE.CylinderGeometry(.16, .16, .3, 10), chromeMat, wid * .28, spec.bodyY + .42, -.6);
    add(new THREE.BoxGeometry(.3, .08, .12), darkMat, wid * .28, spec.bodyY + .5, -.6);
  }
  if (parts.includes('grippy')) {
    for (const [x, , z] of wheelPositions) {
      const g = add(new THREE.BoxGeometry(wheelW * .2, wheelR * 1.2, wheelR * 1.2), new THREE.MeshStandardMaterial({ color: 0x171a1f, roughness: .95 }), x + (x < 0 ? -.08 : .08), wheelR, z);
    }
  }
  if (parts.includes('shocks')) {
    const springMat = new THREE.MeshStandardMaterial({ color: 0xffd24f, metalness: .8, roughness: .25 });
    for (const [x, , z] of wheelPositions) {
      add(new THREE.CylinderGeometry(.05, .05, .34, 8), springMat, x * .82, wheelR + .05, z);
    }
  }
  if (parts.includes('bumper')) {
    add(makeRoundedBoxGeo(wid * 1.04, .2, .22, .06), darkMat, 0, spec.bodyY - .16, len / 2 + .1);
    add(new THREE.BoxGeometry(wid * .9, .03, .04), chromeMat, 0, spec.bodyY - .06, len / 2 + .21);
  }
  if (parts.includes('magnet')) {
    const magMat = new THREE.MeshStandardMaterial({ color: 0xdfe5ee, metalness: 1, roughness: .2 });
    const ring = add(new THREE.TorusGeometry(.2, .06, 8, 20), magMat, 0, spec.bodyY + .1, rearZ - .06);
    ring.rotation.y = Math.PI / 2;
    const red = add(new THREE.TorusGeometry(.2, .06, 8, 20, Math.PI), new THREE.MeshStandardMaterial({ color: 0xd92129, metalness: .6, roughness: .3 }), 0, spec.bodyY + .1, rearZ - .05);
    red.rotation.y = Math.PI / 2;
  }

  // headlight cone (race)
  if (race) {
    const coneMat = new THREE.MeshBasicMaterial({ color: 0xfff1c0, transparent: true, opacity: .12, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
    const coneGeo = new THREE.ConeGeometry(1.15, 6.5, 14, 1, true);
    for (const sx of [-.3, .3]) {
      const c = new THREE.Mesh(coneGeo, coneMat);
      c.rotation.x = -Math.PI / 2;
      c.position.set(sx * wid, spec.bodyY + .18, len / 2 + 3.1);
      group.add(c);
    }
  }

  // contact shadow
  const sh = new THREE.Mesh(new THREE.PlaneGeometry(wid * 1.5, len * 1.15), new THREE.MeshBasicMaterial({ map: getContactShadow(), transparent: true, opacity: .9, depthWrite: false }));
  sh.rotation.x = -Math.PI / 2; sh.position.y = .012; sh.renderOrder = 2;
  group.add(sh);

  group.userData.spec = spec;
  group.userData.paintMat = paintMat;
  group.userData.body = body;
  group.userData.wheels = wheelGroup;
  return group;
}

function disposeCar(group) {
  group.traverse(o => {
    if (o.geometry) o.geometry.dispose();
  });
  (group.userData.disposables || []).forEach(g => { try { g.dispose(); } catch (e) {} });
}

/* ---------- SHOWROOM ---------- */
const showroom = {
  ready: false, scene: null, camera: null, renderer: null, holder: null, car: null,
  platform: null, turntable: null, rot: -.35, targetRot: -.35, dist: 8.4, targetDist: 8.4,
  drag: false, lastX: 0, lastY: 0, autoSpinAngle: 0, builtSig: '',
  init() {
    if (this.ready) return;
    const host = $('#showroom-canvas');
    if (!host || !window.THREE) return;
    const w = host.clientWidth || 600, h = host.clientHeight || 450;
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(w, h);
    renderer.setClearColor(0x000000, 0);
    renderer.outputEncoding = THREE.sRGBEncoding;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    host.appendChild(renderer.domElement);
    this.renderer = renderer;
    const scene = new THREE.Scene();
    this.scene = scene;
    const camera = new THREE.PerspectiveCamera(34, w / h, .1, 100);
    camera.position.set(0, 3.2, 8.4);
    this.camera = camera;

    // environment
    const pmrem = new THREE.PMREMGenerator(renderer);
    pmrem.compileEquirectangularShader();
    const envScene = new THREE.Scene();
    envScene.background = new THREE.Color(0x0a0d12);
    const room = new THREE.Mesh(new THREE.BoxGeometry(30, 18, 30), new THREE.MeshBasicMaterial({ color: 0x10141c, side: THREE.BackSide }));
    room.position.y = 4; envScene.add(room);
    const panel = (color, x, y, z, sx, sy, ry = 0) => {
      const m = new THREE.Mesh(new THREE.PlaneGeometry(sx, sy), new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide }));
      m.position.set(x, y, z); m.rotation.y = ry; envScene.add(m);
    };
    panel(0xffffff, 0, 12, 0, 14, 8);              // overhead softbox
    panel(0xbfe9ff, -11, 5, 2, 8, 10, Math.PI / 2); // cool side
    panel(0xffd8c2, 11, 4, -1, 7, 9, -Math.PI / 2);// warm side
    panel(0x8f7bff, 0, 5, -13, 10, 7);             // back accent
    panel(0x2d3545, 0, -1, 0, 30, 30, 0);
    // bright strips
    for (let i = 0; i < 5; i++) panel(0xffffff, -7 + i * 3.5, 9.5, 4, .7, 5);
    const envRT = pmrem.fromScene(envScene, .02);
    scene.environment = envRT.texture;
    ENV_TEXTURE = envRT.texture;
    pmrem.dispose();

    // lights — 3 point studio
    const hemi = new THREE.HemisphereLight(0xdfeaff, 0x151a22, .55); scene.add(hemi);
    const key = new THREE.DirectionalLight(0xffffff, 2.1);
    key.position.set(5, 8, 5); key.castShadow = true;
    key.shadow.mapSize.width = 1024; key.shadow.mapSize.height = 1024;
    key.shadow.camera.left = -6; key.shadow.camera.right = 6; key.shadow.camera.top = 6; key.shadow.camera.bottom = -6;
    key.shadow.camera.near = .5; key.shadow.camera.far = 25; key.shadow.bias = -.0008;
    scene.add(key);
    const fill = new THREE.DirectionalLight(0x9fd8ff, .85); fill.position.set(-7, 4, 3); scene.add(fill);
    const rim = new THREE.SpotLight(0xff7ad9, 2.2, 22, Math.PI / 5, .6, 1.2);
    rim.position.set(-2, 5, -8); rim.target.position.set(0, .6, 0); scene.add(rim, rim.target);
    scene.add(new THREE.PointLight(0xc6ff3d, .55, 14).translateY(2.5));

    // floor
    const floor = new THREE.Mesh(new THREE.CircleGeometry(14, 64), new THREE.MeshStandardMaterial({ color: 0x0b0e14, metalness: .55, roughness: .42, envMapIntensity: .7 }));
    floor.rotation.x = -Math.PI / 2; floor.position.y = -.26; floor.receiveShadow = true; scene.add(floor);
    const ring = new THREE.Mesh(new THREE.RingGeometry(3.3, 3.42, 80), new THREE.MeshBasicMaterial({ color: 0xc6ff3d, transparent: true, opacity: .35, side: THREE.DoubleSide }));
    ring.rotation.x = -Math.PI / 2; ring.position.y = -.24; scene.add(ring);
    const ring2 = new THREE.Mesh(new THREE.RingGeometry(4.6, 4.64, 80), new THREE.MeshBasicMaterial({ color: 0x39e7ff, transparent: true, opacity: .12, side: THREE.DoubleSide }));
    ring2.rotation.x = -Math.PI / 2; ring2.position.y = -.24; scene.add(ring2);
    // radial glow disc under platform
    const disc = new THREE.Mesh(new THREE.CircleGeometry(3.1, 48), new THREE.MeshBasicMaterial({ color: 0x1a2436, transparent: true, opacity: .55 }));
    disc.rotation.x = -Math.PI / 2; disc.position.y = -.23; scene.add(disc);

    this.turntable = new THREE.Group(); scene.add(this.turntable);
    const platform = new THREE.Mesh(new THREE.CylinderGeometry(2.85, 3.0, .22, 72), new THREE.MeshPhysicalMaterial({ color: 0x12161f, metalness: .8, roughness: .22, clearcoat: .9, clearcoatRoughness: .1, envMapIntensity: .9 }));
    platform.position.y = -.15; platform.receiveShadow = true;
    this.platform = platform; this.turntable.add(platform);
    const plRing = new THREE.Mesh(new THREE.TorusGeometry(2.88, .025, 8, 100), new THREE.MeshBasicMaterial({ color: 0xc6ff3d }));
    plRing.rotation.x = Math.PI / 2; plRing.position.y = -.04; this.turntable.add(plRing);

    this.holder = new THREE.Group(); this.turntable.add(this.holder);

    this.bindEvents(host);
    this.applyConfig();
    this.ready = true;
    this.resize();
  },
  bindEvents(host) {
    const el = this.renderer.domElement;
    let lastTap = 0;
    el.addEventListener('pointerdown', (e) => {
      this.drag = true; this.lastX = e.clientX; this.lastY = e.clientY;
      el.setPointerCapture(e.pointerId);
      const now = performance.now(); if (now - lastTap < 300) this.toggleSpin();
      lastTap = now;
    });
    el.addEventListener('pointermove', (e) => {
      if (!this.drag) return;
      const dx = e.clientX - this.lastX;
      this.targetRot += dx * .011;
      this.rot = this.targetRot;
      this.autoSpinAngle = 0;
      this.lastX = e.clientX; this.lastY = e.clientY;
    });
    const end = () => { this.drag = false; };
    el.addEventListener('pointerup', end); el.addEventListener('pointercancel', end); el.addEventListener('pointerleave', end);
    el.addEventListener('wheel', (e) => {
      e.preventDefault();
      this.targetDist = clamp(this.targetDist + Math.sign(e.deltaY) * .6, 5.4, 12.5);
    }, { passive: false });
    // pinch
    let pinchStart = null;
    el.addEventListener('touchstart', (e) => {
      if (e.touches.length === 2) {
        pinchStart = Math.hypot(e.touches[0].clientX - e.touches[1].clientX, e.touches[0].clientY - e.touches[1].clientY);
      }
    }, { passive: true });
    el.addEventListener('touchmove', (e) => {
      if (e.touches.length === 2 && pinchStart) {
        const d = Math.hypot(e.touches[0].clientX - e.touches[1].clientX, e.touches[0].clientY - e.touches[1].clientY);
        this.targetDist = clamp(this.targetDist + (pinchStart - d) * .025, 5.4, 12.5);
        pinchStart = d;
      }
    }, { passive: true });
    el.addEventListener('touchend', () => { pinchStart = null; }, { passive: true });
    new ResizeObserver(() => this.resize()).observe(host);
  },
  toggleSpin() {
    S.autospin = !S.autospin; save(); this.updateSpinBtn(); Sfx.click();
  },
  updateSpinBtn() {
    const btn = $('#autoSpinBtn'); if (!btn) return;
    btn.classList.toggle('primary', S.autospin);
    $('#spinDot').style.background = S.autospin ? '#0c1206' : '#667085';
    btn.style.borderColor = S.autospin ? 'rgba(198,255,61,.6)' : '';
  },
  applyConfig() {
    if (!this.ready) return;
    const sig = [S.paint, S.model, S.wheels, ...S.equippedParts].join('|');
    if (sig === this.builtSig && this.car) return;
    if (this.car) { this.holder.remove(this.car); disposeCar(this.car); }
    this.car = buildCar({ paint: S.paint, model: S.model, wheels: S.wheels, parts: S.equippedParts });
    this.holder.add(this.car);
    this.builtSig = sig;
    this.car.scale.setScalar(.94);
    this.car.position.y = .02;
  },
  renderAll() {
    if (!this.ready) this.init();
    if (!this.ready) return;
    this.applyConfig(); this.updateSpinBtn(); this.resize();
  },
  resize() {
    if (!this.ready) return;
    const host = $('#showroom-canvas');
    if (!host || host.clientWidth < 10) return;
    const w = host.clientWidth, h = host.clientHeight;
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
    const aspect = w / h;
    this.camera.fov = aspect < .9 ? 42 : aspect > 1.7 ? 30 : 34;
    this.camera.updateProjectionMatrix();
  },
  update(dt) {
    if (!this.ready) return;
    if (S.autospin && !this.drag) {
      this.autoSpinAngle += dt * .35;
      this.targetRot = this.rot = this.targetRot + dt * 0; // noop keeps drag offset
      this.holder.rotation.y += dt * .35;
    }
    if (this.drag) { this.holder.rotation.y = this.rot; }
    else if (!S.autospin) { this.holder.rotation.y = lerp(this.holder.rotation.y, this.rot, .08); }
    this.dist = lerp(this.dist, this.targetDist, .12);
    const targetY = 2.6 + (this.dist - 8.4) * .22;
    this.camera.position.set(0, targetY, this.dist);
    this.camera.lookAt(0, .72, 0);
    this.renderer.render(this.scene, this.camera);
  }
};

/* ---------- main animation loop ---------- */
let lastT = performance.now();
function mainLoop(t) {
  const dt = Math.min(.05, (t - lastT) / 1000 || 0);
  lastT = t;
  if (activeTab === 'customize' && !document.hidden && $('#page-customize').classList.contains('hidden') === false) {
    showroom.update(dt);
  }
  Race.tick(dt);
  Hub.tick(dt);
  requestAnimationFrame(mainLoop);
}
requestAnimationFrame(mainLoop);

