--- index.html
+++ index.html
@@ -1216,7 +1216,532 @@
 function terrainName(id) { const t = TERRAINS.find(x => x.id === id) || TERRAINS[0]; return t.name; }

 function renderCurrencyCompact() { updateCurrencyHud(); }

+/* ============================================================
+   THREE.JS — CAR BUILDER + SHOWROOM
+   ============================================================ */
+let ENV_TEXTURE = null;
+
+function makeRoundedBoxGeo(w, h, d, r = .12, curveSeg = 5) {
+  r = Math.min(r, Math.min(w, d) / 2 - .001);
+  const shape = new THREE.Shape();
