/* ============================================================
   TRACK BUILDER (2D canvas)
   ============================================================ */
const TOOLS = [
  { id: 'straight', name: 'Straight', em: '➡️' },
  { id: 'curve',    name: 'Curve',    em: '↱' },
  { id: 'jump',     name: 'Jump',     em: '🚀' },
  { id: 'loop',     name: 'Loop',     em: '➰' },
  { id: 'bridge',   name: 'Bridge',   em: '🌉' },
  { id: 'start',    name: 'Start Line', em: '🏁' },
  { id: 'erase',    name: 'Erase',    em: '✖️' },
];
let activeTool = 'straight';
let activeRot = 0;
let lastTile = null;
let hoverTile = null;
let painting = false;
let tbCanvas = null, tbCtx = null;

function initTrackToolbar() {
  const wrap = $('#trackToolbar');
  if (!wrap) return;
  wrap.innerHTML = TOOLS.map(t => `<button class="tool-btn" data-tool="${t.id}"><span class="em">${t.em}</span>${t.name}</button>`).join('');
  $$('#trackToolbar [data-tool]').forEach(btn => btn.addEventListener('click', () => {
    activeTool = btn.dataset.tool; Sfx.click(); syncToolButtons();
    if (activeTool === 'erase') lastTile = null;
  }));
  syncToolButtons();
}
function syncToolButtons() {
  $$('#trackToolbar [data-tool]').forEach(b => b.classList.toggle('active', b.dataset.tool === activeTool));
  const rb = $('#rotateBtn'); if (rb) rb.innerHTML = `⟳ Rotate ${activeRot * 90}°`;
}
function drawTrackCanvas() {
  if (!tbCanvas) {
    tbCanvas = $('#trackCanvas'); if (!tbCanvas) return;
    tbCtx = tbCanvas.getContext('2d');
    bindTrackCanvas();
  }
  const rect = tbCanvas.getBoundingClientRect();
  if (rect.width < 4) return;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const W = rect.width, H = rect.width * 5 / 8;
  if (tbCanvas.width !== Math.round(W * dpr) || tbCanvas.height !== Math.round(H * dpr)) {
    tbCanvas.width = Math.round(W * dpr); tbCanvas.height = Math.round(H * dpr);
    tbCanvas.style.height = H + 'px';
  }
  const ctx = tbCtx;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, W, H);
  const cw = W / 8, ch = H / 5;
  const terrain = TERRAINS.find(t => t.id === S.terrain) || TERRAINS[0];
  ctx.fillStyle = terrain.bg; ctx.fillRect(0, 0, W, H);
  drawTerrainPattern(ctx, W, H, terrain);

  // tiles
  for (let y = 0; y < 5; y++) for (let x = 0; x < 8; x++) {
    const tile = S.trackGrid[y] && S.trackGrid[y][x];
    if (tile) drawTile(ctx, x * cw, y * ch, cw, ch, tile.part, tile.rot || 0, terrain);
  }
  // grid lines
  ctx.strokeStyle = 'rgba(255,255,255,.09)'; ctx.lineWidth = 1;
  for (let x = 0; x <= 8; x++) { ctx.beginPath(); ctx.moveTo(Math.round(x * cw) + .5, 0); ctx.lineTo(Math.round(x * cw) + .5, H); ctx.stroke(); }
  for (let y = 0; y <= 5; y++) { ctx.beginPath(); ctx.moveTo(0, Math.round(y * ch) + .5); ctx.lineTo(W, Math.round(y * ch) + .5); ctx.stroke(); }
  // hover
  if (hoverTile) {
    ctx.strokeStyle = 'rgba(198,255,61,.85)'; ctx.lineWidth = 2;
    ctx.strokeRect(hoverTile.x * cw + 2, hoverTile.y * ch + 2, cw - 4, ch - 4);
    if (activeTool !== 'erase' && activeTool !== 'start') {
      ctx.save(); ctx.globalAlpha = .5; drawTile(ctx, hoverTile.x * cw, hoverTile.y * ch, cw, ch, activeTool, activeRot, terrain); ctx.restore();
    }
  }
  if (lastTile) {
    ctx.strokeStyle = 'rgba(57,231,255,.8)'; ctx.lineWidth = 1.5; ctx.setLineDash([4, 3]);
    ctx.strokeRect(lastTile.x * cw + 1, lastTile.y * ch + 1, cw - 2, ch - 2);
    ctx.setLineDash([]);
  }
  // corner label
  ctx.fillStyle = 'rgba(255,255,255,.4)'; ctx.font = '600 9px Inter, sans-serif'; ctx.textAlign = 'right';
  ctx.fillText(`${terrain.name.toUpperCase()} · ${TIMES[S.time].name.toUpperCase()}`, W - 8, H - 7);
}
function drawTerrainPattern(ctx, W, H, terrain) {
  const rng = mulberry32(hashGrid(S.trackGrid) ^ 0x9e37);
  ctx.save();
  if (terrain.id === 'grass') {
    for (let i = 0; i < 120; i++) { const x = rng() * W, y = rng() * H; ctx.strokeStyle = `rgba(${110 + rng() * 40},${150 + rng() * 40},${70},.4)`; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + rng() * 3 - 1, y - 3 - rng() * 3); ctx.stroke(); }
  } else if (terrain.id === 'sand') {
    for (let i = 0; i < 70; i++) { ctx.strokeStyle = 'rgba(255,235,190,.22)'; ctx.lineWidth = 1; ctx.beginPath(); const x = rng() * W, y = rng() * H; ctx.arc(x, y, 8 + rng() * 22, .2, 1.4); ctx.stroke(); }
  } else if (terrain.id === 'snow') {
    for (let i = 0; i < 110; i++) { ctx.fillStyle = 'rgba(255,255,255,.55)'; ctx.beginPath(); ctx.arc(rng() * W, rng() * H, .7 + rng() * 1.6, 0, 7); ctx.fill(); }
  } else if (terrain.id === 'city') {
    for (let i = 0; i < 26; i++) { const x = rng() * W, y = rng() * H, w = 16 + rng() * 38, h = 12 + rng() * 30; ctx.fillStyle = 'rgba(22,25,31,.34)'; ctx.fillRect(x, y, w, h); ctx.strokeStyle = 'rgba(255,255,255,.05)'; ctx.strokeRect(x + .5, y + .5, w, h); }
  } else if (terrain.id === 'lava') {
    for (let i = 0; i < 22; i++) {
      ctx.strokeStyle = `rgba(255,${70 + rng() * 70},20,${.22 + rng() * .35})`; ctx.lineWidth = 1 + rng() * 1.5;
      ctx.beginPath(); let x = rng() * W, y = rng() * H; ctx.moveTo(x, y);
      for (let j = 0; j < 4; j++) { x += rng() * 30 - 15; y += rng() * 24 - 12; ctx.lineTo(x, y); } ctx.stroke();
    }
  } else if (terrain.id === 'jungle') {
    for (let i = 0; i < 40; i++) { ctx.fillStyle = `rgba(${30 + rng() * 30},${90 + rng() * 60},${40},.4)`; ctx.beginPath(); ctx.ellipse(rng() * W, rng() * H, 8 + rng() * 16, 4 + rng() * 8, rng() * 6, 0, 7); ctx.fill(); }
  } else if (terrain.id === 'neon') {
    ctx.strokeStyle = 'rgba(57,231,255,.13)'; ctx.lineWidth = 1;
    for (let x = 0; x < W; x += 22) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke(); }
    for (let y = 0; y < H; y += 22) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke(); }
    for (let i = 0; i < 18; i++) { ctx.fillStyle = rng() > .5 ? 'rgba(255,79,216,.4)' : 'rgba(57,231,255,.4)'; ctx.fillRect(rng() * W, rng() * H, 2, 2); }
  } else if (terrain.id === 'candy') {
    for (let i = 0; i < 60; i++) { ctx.fillStyle = ['rgba(255,255,255,.32)', 'rgba(255,214,235,.35)', 'rgba(220,130,190,.3)'][i % 3]; ctx.beginPath(); ctx.arc(rng() * W, rng() * H, 2 + rng() * 4, 0, 7); ctx.fill(); }
  } else if (terrain.id === 'swamp') {
    for (let i = 0; i < 26; i++) { ctx.fillStyle = 'rgba(40,70,40,.4)'; ctx.beginPath(); ctx.ellipse(rng() * W, rng() * H, 10 + rng() * 24, 4 + rng() * 12, rng(), 0, 7); ctx.fill(); ctx.strokeStyle = 'rgba(120,160,70,.18)'; ctx.stroke(); }
  } else if (terrain.id === 'space') {
