const TOOLS = [
  { id: 'straight', name: 'Straight', em: '➡️' },
  { id: 'curve',    name: 'Curve',    em: '↱' },
  { id: 'jump',     name: 'Jump',     em: '🚀' },
  { id: 'loop',     name: 'Loop',     em: '➰' },
  { id: 'bridge',   name: 'Bridge',   em: '🌉' },
  { id: 'start',    name: 'Start Line', em: '🏁' },
  { id: 'erase',    name: 'Erase',    em: '✖️' },
];
let activeTool = 'straight';
let activeRot = 0;
let lastTile = null;
let hoverTile = null;
let painting = false;
let tbCanvas = null, tbCtx = null;

function initTrackToolbar() {
  const wrap = $('#trackToolbar');
  if (!wrap) return;
  wrap.innerHTML = TOOLS.map(t => `<button class="tool-btn" data-tool="${t.id}"><span class="em">${t.em}</span>${t.name}</button>`).join('');
  $$('#trackToolbar [data-tool]').forEach(btn => btn.addEventListener('click', () => {
    activeTool = btn.dataset.tool; Sfx.click(); syncToolButtons();
    if (activeTool === 'erase') lastTile = null;
  }));
  syncToolButtons();
}
function syncToolButtons() {
  $$('#trackToolbar [data-tool]').forEach(b => b.classList.toggle('active', b.dataset.tool === activeTool));
  const rb = $('#rotateBtn'); if (rb) rb.innerHTML = `⟳ Rotate ${activeRot * 90}°`;
}
function drawTrackCanvas() {
  if (!tbCanvas) {
    tbCanvas = $('#trackCanvas'); if (!tbCanvas) return;
    tbCtx = tbCanvas.getContext('2d');
    bindTrackCanvas();
  }
