  ctx.fillStyle = 'rgba(255,255,255,.4)'; ctx.font = '600 9px Inter, sans-serif'; ctx.textAlign = 'right';
  ctx.fillText(`${terrain.name.toUpperCase()} · ${TIMES[S.time].name.toUpperCase()}`, W - 8, H - 7);
}
function drawTerrainPattern(ctx, W, H, terrain) {
  const rng = mulberry32(hashGrid(S.trackGrid) ^ 0x9e37);
