  } else if (terrain.id === 'swamp') {
    for (let i = 0; i < 26; i++) { ctx.fillStyle = 'rgba(40,70,40,.4)'; ctx.beginPath(); ctx.ellipse(rng() * W, rng() * H, 10 + rng() * 24, 4 + rng() * 12, rng(), 0, 7); ctx.fill(); ctx.strokeStyle = 'rgba(120,160,70,.18)'; ctx.stroke(); }
  } else if (terrain.id === 'space') {
    for (let i = 0; i < 100; i++) { const a = rng(); ctx.fillStyle = `rgba(255,255,255,${.2 + a * .7})`; ctx.fillRect(rng() * W, rng() * H, a > .9 ? 2 : 1, a > .9 ? 2 : 1); }
  } else if (terrain.id === 'gold') {
    for (let i = 0; i < 50; i++) { ctx.fillStyle = `rgba(255,${205 + rng() * 50},100,${.18 + rng() * .4})`; ctx.beginPath(); ctx.arc(rng() * W, rng() * H, .8 + rng() * 2, 0, 7); ctx.fill(); }
  } else if (terrain.id === 'prism') {
    for (let i = 0; i < 16; i++) {
      const x = rng() * W, y = rng() * H, s = 14 + rng() * 40;
      const grd = ctx.createLinearGradient(x, y, x + s, y + s);
      const hue = (rng() * 360) | 0;
      grd.addColorStop(0, `hsla(${hue},90%,65%,.12)`); grd.addColorStop(1, `hsla(${hue + 90},90%,65%,.02)`);
      ctx.fillStyle = grd; ctx.beginPath(); ctx.moveTo(x, y + s); ctx.lineTo(x + s, y + s * .3); ctx.lineTo(x + s * 1.3, y + s); ctx.closePath(); ctx.fill();
