}
function roundRectPath(ctx, x, y, w, h, r) {
  r = Math.min(r, w / 2, h / 2);
  ctx.beginPath(); ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r); ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath();
}
function drawTile(ctx, x, y, w, h, part, rot, terrain) {
  const dark = terrain.id === 'snow' ? '#3a424c' : terrain.id === 'sand' ? '#59524a' : terrain.id === 'lava' ? '#38292a' : terrain.id === 'neon' ? '#262a45' : terrain.id === 'candy' ? '#5c4d5b' : terrain.id === 'prism' ? '#3a3452' : '#3a3d43';
  const light = terrain.id === 'snow' ? '#59636d' : '#565b62';
