    ctx.strokeStyle = asphalt; ctx.lineWidth = lw * 1.3;
    ctx.beginPath(); ctx.arc(-w / 2, -h / 2, Math.min(w, h) * .82, 0, Math.PI / 2); ctx.stroke();
    ctx.strokeStyle = 'rgba(255,255,255,.62)'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(-w / 2, -h / 2, Math.min(w, h) * .82 - lw * .62, 0, Math.PI / 2); ctx.stroke();
    ctx.beginPath(); ctx.arc(-w / 2, -h / 2, Math.min(w, h) * .82 + lw * .62, 0, Math.PI / 2); ctx.stroke();
    ctx.strokeStyle = 'rgba(230,72,72,.8)'; ctx.lineWidth = 2;
    for (let i = 0; i < 4; i++) { const a0 = i * Math.PI / 8; ctx.beginPath(); ctx.arc(-w / 2, -h / 2, Math.min(w, h) * .82 + lw * .64, a0, a0 + Math.PI / 16); ctx.stroke(); }
  } else if (part === 'jump') {
    ctx.fillStyle = asphalt; ctx.fillRect(-w / 2, -lw / 2, w, lw);
    ctx.strokeStyle = '#e8ecf2'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(-w / 2, -lw / 2); ctx.lineTo(w / 2, -lw / 2); ctx.moveTo(-w / 2, lw / 2); ctx.lineTo(w / 2, lw / 2); ctx.stroke();
    ctx.fillStyle = 'rgba(0,0,0,.4)'; ctx.fillRect(w * .06, -lw / 2, w * .1, lw);
    for (let i = 0; i < 2; i++) {
      ctx.strokeStyle = '#ffd24f'; ctx.lineWidth = 2.5;
      ctx.beginPath(); ctx.moveTo(-w * .28 + i * w * .14, lw * .28); ctx.lineTo(-w * .2 + i * w * .14, 0); ctx.lineTo(-w * .12 + i * w * .14, lw * .28); ctx.stroke();
    }
    ctx.fillStyle = '#ffd24f'; ctx.font = '700 7px Inter,sans-serif'; ctx.textAlign = 'center'; ctx.fillText('JUMP', 0, -lw * .34);
    ctx.fillStyle = 'rgba(255,210,79,.2)'; ctx.fillRect(-w / 2, -lw / 2, w, lw);
  } else if (part === 'loop') {
    ctx.fillStyle = asphalt; ctx.fillRect(-w / 2, -lw / 2, w, lw);
    ctx.strokeStyle = 'rgba(255,79,216,.9)'; ctx.lineWidth = 2.4;
    ctx.beginPath(); ctx.ellipse(0, 0, w * .18, h * .16, 0, 0, 7); ctx.stroke();
    ctx.strokeStyle = 'rgba(255,255,255,.55)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.ellipse(0, 0, w * .18, h * .16, 0, 0, 7); ctx.stroke();
    ctx.fillStyle = 'rgba(255,79,216,.14)'; ctx.beginPath(); ctx.ellipse(0, 0, w * .18, h * .16, 0, 0, 7); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.8)'; ctx.font = '700 7px Inter,sans-serif'; ctx.textAlign = 'center'; ctx.fillText('LOOP', 0, lw * .36);
  } else if (part === 'bridge') {
    ctx.fillStyle = '#16181d'; ctx.fillRect(-lw / 2, -h / 2, lw, h);
    ctx.globalAlpha = .5; ctx.fillStyle = asphalt; ctx.fillRect(-lw / 2, -h / 2, lw, h); ctx.globalAlpha = 1;
    ctx.strokeStyle = 'rgba(255,255,255,.22)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(-lw / 2, -h / 2); ctx.lineTo(-lw / 2, h / 2); ctx.moveTo(lw / 2, -h / 2); ctx.lineTo(lw / 2, h / 2); ctx.stroke();
    ctx.fillStyle = 'rgba(0,0,0,.45)'; ctx.fillRect(-w / 2, -lw / 2 + 5, w, lw);
    ctx.fillStyle = light; ctx.fillRect(-w / 2, -lw / 2, w, lw);
    ctx.strokeStyle = '#f2c94c'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(-w / 2, -lw / 2); ctx.lineTo(w / 2, -lw / 2); ctx.moveTo(-w / 2, lw / 2); ctx.lineTo(w / 2, lw / 2); ctx.stroke();
    ctx.strokeStyle = 'rgba(0,0,0,.35)'; ctx.lineWidth = 1;
    for (let i = 0; i < 4; i++) { ctx.beginPath(); ctx.moveTo(-w / 2 + i * w / 4, -lw / 2); ctx.lineTo(-w / 2 + i * w / 4, lw / 2); ctx.stroke(); }
    ctx.fillStyle = 'rgba(255,255,255,.85)'; ctx.font = '700 7px Inter,sans-serif'; ctx.textAlign = 'center'; ctx.fillText('BRIDGE', 0, -lw / 2 - 5);
  } else if (part === 'start') {
    ctx.fillStyle = asphalt; ctx.fillRect(-w / 2, -lw / 2, w, lw);
    ctx.strokeStyle = '#e8ecf2'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(-w / 2, -lw / 2); ctx.lineTo(w / 2, -lw / 2); ctx.moveTo(-w / 2, lw / 2); ctx.lineTo(w / 2, lw / 2); ctx.stroke();
    ctx.fillStyle = '#f4f7fb'; ctx.fillRect(-w / 2, -lw / 2, w * .14, lw);
    for (let r = 0; r < 4; r++) for (let c = 0; c < 2; c++) { ctx.fillStyle = (r + c) % 2 ? '#15171c' : '#ffffff'; ctx.fillRect(-w / 2 + c * w * .07, -lw / 2 + r * lw / 4, w * .07, lw / 4); }
    ctx.fillStyle = '#c6ff3d'; ctx.font = '800 8px Inter,sans-serif'; ctx.textAlign = 'left'; ctx.fillText('START', -w * .27, 3);
    ctx.strokeStyle = 'rgba(255,255,255,.55)'; ctx.lineWidth = 1; ctx.setLineDash([4, 4]); ctx.beginPath(); ctx.moveTo(-w * .2, 0); ctx.lineTo(w / 2, 0); ctx.stroke(); ctx.setLineDash([]);
  } else {
    ctx.fillStyle = asphalt; ctx.fillRect(-w / 2, -lw / 2, w, lw);
    const g = ctx.createLinearGradient(0, -lw / 2, 0, lw / 2);
    g.addColorStop(0, 'rgba(255,255,255,.055)'); g.addColorStop(.5, 'rgba(255,255,255,0)'); g.addColorStop(1, 'rgba(0,0,0,.16)');
    ctx.fillStyle = g; ctx.fillRect(-w / 2, -lw / 2, w, lw);
    ctx.strokeStyle = 'rgba(235,240,248,.72)'; ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.moveTo(-w / 2, -lw / 2); ctx.lineTo(w / 2, -lw / 2); ctx.moveTo(-w / 2, lw / 2); ctx.lineTo(w / 2, lw / 2); ctx.stroke();
    ctx.strokeStyle = 'rgba(230,72,72,.75)'; ctx.lineWidth = 2;
    for (let i = -3; i < 4; i += 2) { ctx.beginPath(); ctx.moveTo(i * w / 8, -lw / 2); ctx.lineTo(i * w / 8 + w / 8, -lw / 2); ctx.stroke(); }
    ctx.strokeStyle = 'rgba(255,236,150,.5)'; ctx.lineWidth = 1.2; ctx.setLineDash([5, 7]);
    ctx.beginPath(); ctx.moveTo(-w / 2, 0); ctx.lineTo(w / 2, 0); ctx.stroke(); ctx.setLineDash([]);
