}
function bindTrackCanvas() {
  if (!tbCanvas) return;
  const cellFromEvent = (e) => {
    const rect = tbCanvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / (rect.width / 8));
    const y = Math.floor((e.clientY - rect.top) / (rect.height / 5));
    return (x >= 0 && x < 8 && y >= 0 && y < 5) ? { x, y } : null;
  };
  const paintCell = (cell) => {
    if (!cell) return;
    if (activeTool === 'erase') S.trackGrid[cell.y][cell.x] = null;
    else S.trackGrid[cell.y][cell.x] = { part: activeTool, rot: activeRot };
    lastTile = cell; save(); drawTrackCanvas(); updateTrackStats();
  };
  tbCanvas.addEventListener('pointerdown', (e) => {
    e.preventDefault(); tbCanvas.setPointerCapture(e.pointerId);
    const cell = cellFromEvent(e); if (!cell) return;
    painting = true; paintCell(cell); Sfx.resume();
  });
  tbCanvas.addEventListener('pointermove', (e) => {
    const cell = cellFromEvent(e);
    if (cell && (!hoverTile || hoverTile.x !== cell.x || hoverTile.y !== cell.y)) { hoverTile = cell; drawTrackCanvas(); }
    if (painting && cell) paintCell(cell);
  });
  tbCanvas.addEventListener('pointerup', () => { painting = false; });
  tbCanvas.addEventListener('pointercancel', () => { painting = false; });
  tbCanvas.addEventListener('pointerleave', () => { painting = false; hoverTile = null; drawTrackCanvas(); });
}
function updateTrackStats() {
  let tiles = 0, curves = 0, special = 0;
  for (const row of S.trackGrid) for (const t of row) if (t) { tiles++; if (t.part === 'curve') curves++; if (t.part === 'jump' || t.part === 'loop' || t.part === 'bridge') special++; }
  $('#statTiles').textContent = tiles; $('#statCurves').textContent = curves; $('#statSpecial').textContent = special;
  const cb = $('#clearTrackBtn'); if (cb) cb.disabled = tiles === 0;
}
function renderTrackBuilder() {
  if (!tbCanvas) { tbCanvas = $('#trackCanvas'); if (tbCanvas) tbCtx = tbCanvas.getContext('2d'); }
  if (!tbCanvas) return;
  initTrackToolbar(); renderTerrainGrid(); renderTimeUI(); renderStakeUI(); renderSavedTracks();
  syncToolButtons();
  $('#terrainBadge').textContent = terrainName(S.terrain);
  $('#terrainBadge').style.color = '#c6ff3d';
  $('#timeBadge').textContent = S.time === 'day' ? '☀️ Day' : S.time === 'sunset' ? '🌇 Sunset' : '🌙 Night';
  const t = TERRAINS.find(x => x.id === S.terrain);
  $('#terrainDesc').textContent = t ? t.desc : '';
  updateTrackStats();
  requestAnimationFrame(() => { drawTrackCanvas(); });
}
function renderTerrainGrid() {
  const grid = $('#terrainGrid'); if (!grid) return;
  grid.innerHTML = TERRAINS.map(t => {
    const owned = S.unlockedTerrains.includes(t.id);
    return `<button class="terrain-tile ${S.terrain === t.id ? 'active' : ''} ${owned ? '' : 'locked'}" data-terrain="${t.id}" style="background:linear-gradient(150deg,${t.bg},${t.bg}aa)">
      <span class="relative z-10">${t.name}${owned ? '' : `<br><span class="text-[8px] text-amber-200">$${t.price}</span>`}</span>
      ${owned ? '' : '<span class="lockbadge">🔒</span>'}
    </button>`;
  }).join('');
  $$('#terrainGrid [data-terrain]').forEach(btn => btn.addEventListener('click', () => selectTerrain(btn.dataset.terrain)));
}
function selectTerrain(id) {
  const t = TERRAINS.find(x => x.id === id); if (!t) return;
  if (S.unlockedTerrains.includes(id)) {
    S.terrain = id; save(); renderTerrainGrid(); renderTrackBuilder(); Sfx.click(); return;
  }
  if (S.cash < t.price) { toast(`Need $${t.price} — win races to unlock ${t.name}`, 'bad'); Sfx.bump(); return; }
  modal(`Unlock ${t.name} Terrain`, `${t.desc}<br><br>Price: <b class="text-amber-300">$${t.price}</b>`, 'Unlock', () => {
    S.cash -= t.price; S.unlockedTerrains.push(id); S.terrain = id;
    Sfx.unlock(); toast(`${t.name} terrain unlocked`, 'key'); save(true); renderTrackBuilder();
  });
}
function renderTimeUI() { $$('#timeSeg button').forEach(b => b.classList.toggle('active', b.dataset.time === S.time)); }
function renderStakeUI() { $$('#stakeSeg button').forEach(b => b.classList.toggle('active', +b.dataset.stake === S.stake)); }
$$('#timeSeg button').forEach(b => b.addEventListener('click', () => { S.time = b.dataset.time; save(); renderTimeUI(); drawTrackCanvas(); $('#timeBadge').textContent = S.time === 'day' ? '☀️ Day' : S.time === 'sunset' ? '🌇 Sunset' : '🌙 Night'; Sfx.click(); }));
$$('#stakeSeg button').forEach(b => b.addEventListener('click', () => { S.stake = +b.dataset.stake; save(); renderStakeUI(); Sfx.click(); }));

$('#rotateBtn').addEventListener('click', () => {
  activeRot = (activeRot + 1) % 4;
  if (lastTile && S.trackGrid[lastTile.y] && S.trackGrid[lastTile.y][lastTile.x]) {
    S.trackGrid[lastTile.y][lastTile.x].rot = (S.trackGrid[lastTile.y][lastTile.x].rot + 1) % 4;
    save();
  }
  syncToolButtons(); drawTrackCanvas(); Sfx.click();
});
$('#sampleOvalBtn').addEventListener('click', () => {
  S.trackGrid = makeSampleOval(); S.lastTrackName = 'Sample Oval'; save(); drawTrackCanvas(); updateTrackStats(); Sfx.click(); toast('Sample oval loaded', 'good');
});
$('#bridgePresetBtn').addEventListener('click', () => {
  S.trackGrid = makeBridgePreset(); S.lastTrackName = 'Bridge Track'; save(); drawTrackCanvas(); updateTrackStats(); Sfx.unlock(); toast('🌉 Bridge Track loaded', 'good');
});
$('#clearTrackBtn').addEventListener('click', () => {
  modal('Clear the track?', 'Removes every tile from the 8 × 5 grid.', 'Clear', () => {
    S.trackGrid = emptyGrid(); lastTile = null; save(); drawTrackCanvas(); updateTrackStats(); toast('Track cleared');
  });
});
$('#saveTrackBtn').addEventListener('click', () => {
  const name = ($('#trackName').value || '').trim() || `Track ${S.tracks.length + 1}`;
  if (S.tracks.length >= 8) { toast('Track library full — delete one first', 'bad'); return; }
  let tiles = 0; for (const row of S.trackGrid) for (const t of row) if (t) tiles++;
  S.tracks.push({ name, grid: JSON.parse(JSON.stringify(S.trackGrid)), terrain: S.terrain, time: S.time, tiles });
  $('#trackName').value = ''; save(true); renderSavedTracks(); renderTrackQuickList(); Sfx.unlock(); toast(`Saved “${name}”`, 'good');
});
function renderSavedTracks() {
  const wrap = $('#savedTracks'); if (!wrap) return;
  if (!S.tracks.length) {
    wrap.innerHTML = `<div class="col-span-full rounded-xl border border-dashed border-white/10 p-3 text-center text-[10.5px] text-slate-500">No tracks saved. Build something, then hit <b class="text-slate-300">Save</b>.</div>`;
    return;
  }
  wrap.innerHTML = S.tracks.map((t, i) => `<div class="flex items-center gap-2 rounded-xl border border-white/[.07] bg-white/[.025] p-2">
    <span class="grid h-8 w-11 shrink-0 place-items-center rounded-md border border-white/10 text-[12px]" style="background:${terrainCss(t.terrain)}">🏁</span>
    <div class="min-w-0 flex-1"><div class="truncate text-[10.5px] font-bold">${escapeHtml(t.name)}</div><div class="text-[8.5px] text-slate-500">${terrainName(t.terrain)} · ${t.time} · ${t.tiles || 0} tiles</div></div>
    <button class="btn small" data-loadtrack="${i}">Load</button>
    <button class="btn small danger !px-2" data-deltrack="${i}">✕</button>
  </div>`).join('');
  $$('#savedTracks [data-loadtrack]').forEach(b => b.addEventListener('click', () => {
    const t = S.tracks[+b.dataset.loadtrack]; if (!t) return;
    S.trackGrid = JSON.parse(JSON.stringify(t.grid)); S.terrain = t.terrain; S.time = t.time; S.lastTrackName = t.name;
    save(); renderTrackBuilder(); Sfx.click(); toast(`Loaded “${escapeHtml(t.name)}”`, 'good');
  }));
  $$('#savedTracks [data-deltrack]').forEach(b => b.addEventListener('click', () => {
    S.tracks.splice(+b.dataset.deltrack, 1); save(true); renderSavedTracks(); renderTrackQuickList(); toast('Track deleted');
  }));
}
$('#startRaceBtn').addEventListener('click', () => {
  const stake = S.stake;
  if (S.cash < stake) { toast(`Need $${stake} for this stake`, 'bad'); Sfx.bump(); return; }
  Sfx.resume();
  Race.start({ stake, laps: 2, mode: 'quick', trackName: S.lastTrackName || 'Custom Circuit' });
});

