      const s = .7 + rng() * .8;
      if (kind === 'trees' || kind === 'jungle') {
        const trunk = new THREE.Mesh(new THREE.CylinderGeometry(.14 * s, .2 * s, 1.5 * s, 6), new THREE.MeshStandardMaterial({ color: 0x5a4128, roughness: .9 }));
        trunk.position.y = .75 * s; g.add(trunk);
        const leafMat = new THREE.MeshStandardMaterial({ color: kind === 'jungle' ? 0x2a7a3e : 0x3e8f45, roughness: .85 });
        for (let j = 0; j < 3; j++) {
          const cone = new THREE.Mesh(new THREE.ConeGeometry((1.2 - j * .25) * s, 1.5 * s, 7), leafMat);
          cone.position.y = (1.7 + j * .75) * s; g.add(cone);
        }
      } else if (kind === 'cacti') {
        const mat = new THREE.MeshStandardMaterial({ color: 0x3d7a46, roughness: .8 });
        const body = new THREE.Mesh(new THREE.CylinderGeometry(.3 * s, .34 * s, 2.4 * s, 8), mat); body.position.y = 1.2 * s; g.add(body);
        const arm = new THREE.Mesh(new THREE.CylinderGeometry(.16 * s, .16 * s, .9 * s, 6), mat); arm.position.set(.4 * s, 1.4 * s, 0); arm.rotation.z = -Math.PI / 2; g.add(arm);
        const arm2 = new THREE.Mesh(new THREE.CylinderGeometry(.14 * s, .14 * s, .7 * s, 6), mat); arm2.position.set(.4 * s, 1.9 * s, 0); g.add(arm2);
      } else if (kind === 'pine') {
        const trunk = new THREE.Mesh(new THREE.CylinderGeometry(.12 * s, .16 * s, 1 * s, 6), new THREE.MeshStandardMaterial({ color: 0x4a3525, roughness: .9 })); trunk.position.y = .5 * s; g.add(trunk);
        const mat = new THREE.MeshStandardMaterial({ color: 0x2e5b47, roughness: .8 });
        for (let j = 0; j < 3; j++) { const c = new THREE.Mesh(new THREE.ConeGeometry((1.1 - j * .22) * s, 1.7 * s, 7), mat); c.position.y = (1.2 + j * .8) * s; g.add(c); }
        const snow = new THREE.Mesh(new THREE.ConeGeometry(.8 * s, .3 * s, 7), new THREE.MeshStandardMaterial({ color: 0xeef6fb, roughness: .8 })); snow.position.y = 3.3 * s; g.add(snow);
      } else if (kind === 'buildings') {
        const h = 3 + rng() * 14, w = 2 + rng() * 3, d = 2 + rng() * 3;
        const mat = new THREE.MeshStandardMaterial({ color: new THREE.Color().setHSL(.58 + rng() * .05, .1, .2 + rng() * .12), roughness: .6, metalness: .2 });
        const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat); b.position.y = h / 2; b.castShadow = true; g.add(b);
        const windowMat = new THREE.MeshBasicMaterial({ color: 0xffd98a });
        for (let wy = 0; wy < Math.min(5, Math.floor(h / 2)); wy++) for (let wx = 0; wx < 2; wx++) {
          if (rng() > .55) continue;
          const win = new THREE.Mesh(new THREE.PlaneGeometry(.35, .3), windowMat);
          win.position.set(-w / 4 + wx * w / 2, 1.2 + wy * 1.8, d / 2 + .01); g.add(win);
        }
      } else if (kind === 'lavarocks') {
        const mat = new THREE.MeshStandardMaterial({ color: 0x2a2020, roughness: .9, metalness: .1 });
        for (let j = 0; j < 3; j++) {
          const r = new THREE.Mesh(new THREE.DodecahedronGeometry((.6 + rng() * .8) * s, 0), mat);
          r.position.set((rng() - .5) * 2.2 * s, .4 * s + rng() * .4, (rng() - .5) * 2.2 * s); r.rotation.set(rng(), rng(), rng()); g.add(r);
        }
        const glow = new THREE.Mesh(new THREE.PlaneGeometry(3 * s, 3 * s), new THREE.MeshBasicMaterial({ color: 0xff5a1f, transparent: true, opacity: .35, blending: THREE.AdditiveBlending, depthWrite: false }));
        glow.rotation.x = -Math.PI / 2; glow.position.y = .03; g.add(glow);
      } else if (kind === 'neon') {
        const mat = new THREE.MeshStandardMaterial({ color: 0x141522, metalness: .6, roughness: .3 });
        const b = new THREE.Mesh(new THREE.BoxGeometry(1.2 * s, 4 + rng() * 6, 1.2 * s), mat); b.position.y = 2 + rng() * 3; g.add(b);
        const col = new THREE.Color().setHSL(rng(), .9, .6);
        const strip = new THREE.Mesh(new THREE.BoxGeometry(.12, 3.5, .12), new THREE.MeshBasicMaterial({ color: col }));
        strip.position.set(.7 * s, 2.2, .7 * s); g.add(strip);
      } else if (kind === 'candy') {
        const stick = new THREE.Mesh(new THREE.CylinderGeometry(.08, .08, 2.2 * s, 6), new THREE.MeshStandardMaterial({ color: 0xffffff }));
        stick.position.y = 1.1 * s; g.add(stick);
        const hue = rng();
        const swirl = new THREE.Mesh(new THREE.TorusGeometry(.7 * s, .24 * s, 8, 22), new THREE.MeshStandardMaterial({ color: new THREE.Color().setHSL(hue, .8, .65), roughness: .3, metalness: .2 }));
        swirl.position.y = 2.7 * s; swirl.rotation.x = .5; g.add(swirl);
      } else if (kind === 'swamp') {
        const pool = new THREE.Mesh(new THREE.CircleGeometry(2 + rng() * 3, 18), new THREE.MeshStandardMaterial({ color: 0x1b3328, roughness: .2, metalness: .6 }));
        pool.rotation.x = -Math.PI / 2; pool.position.y = .02; g.add(pool);
        const reedMat = new THREE.MeshStandardMaterial({ color: 0x6e7a32, roughness: .9 });
        for (let j = 0; j < 5; j++) { const r = new THREE.Mesh(new THREE.CylinderGeometry(.04, .05, 1 + rng() * 1.2, 5), reedMat); r.position.set((rng() - .5) * 3, .7, (rng() - .5) * 3); r.rotation.z = (rng() - .5) * .3; g.add(r); }
      } else if (kind === 'space') {
        const mat = new THREE.MeshStandardMaterial({ color: 0x8a95b8, roughness: .8 });
        const r = new THREE.Mesh(new THREE.DodecahedronGeometry((.5 + rng() * 1.2) * s, 0), mat);
        r.position.y = 1 + rng() * 4; r.rotation.set(rng() * 3, rng() * 3, rng() * 3); g.add(r);
        const ringMat = new THREE.MeshBasicMaterial({ color: 0x39e7ff, transparent: true, opacity: .4 });
        const ring = new THREE.Mesh(new THREE.RingGeometry(1.4 * s, 1.5 * s, 30), ringMat);
        ring.rotation.x = -Math.PI / 2; ring.position.y = .05; g.add(ring);
      } else if (kind === 'gold') {
        const mat = new THREE.MeshPhysicalMaterial({ color: 0xffd257, metalness: 1, roughness: .18, clearcoat: 1 });
        for (let j = 0; j < 3; j++) {
          const b = new THREE.Mesh(new THREE.BoxGeometry((1 + rng()) * s, (.3 + rng() * .5) * s, (1 + rng()) * s), mat);
          b.position.set((rng() - .5) * 3, .4 + rng(), (rng() - .5) * 3); b.rotation.y = rng() * 3; g.add(b);
        }
      } else if (kind === 'prism') {
        const hue = rng();
        const mat = new THREE.MeshPhysicalMaterial({ color: new THREE.Color().setHSL(hue, .7, .6), metalness: .2, roughness: .05, clearcoat: 1, transmission: .4, transparent: true, opacity: .88 });
        const c = new THREE.Mesh(new THREE.IcosahedronGeometry((.8 + rng() * 1.2) * s, 0), mat);
        c.position.y = 1.2 * s; c.rotation.set(rng() * 3, rng() * 3, rng() * 3); g.add(c);
      }
      g.traverse(o => { if (o.isMesh) { o.castShadow = true; } });
      world.add(g);
    }
  },

  buildDust(scene) {
    const n = 380;
    const geo = new THREE.BufferGeometry();
    const arr = [];
    for (let i = 0; i < n; i++) arr.push((Math.random() - .5) * 200, .3 + Math.random() * 8, (Math.random() - .5) * 160);
    geo.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3));
    const mat = new THREE.PointsMaterial({ color: this.terrain.dust, size: .22, transparent: true, opacity: .5, depthWrite: false });
    const pts = new THREE.Points(geo, mat);
    scene.add(pts); this.dust = pts;
  },

  buildCars() {
    const paints = ['blue', 'yellow', 'green', 'white', 'red'].filter(p => p !== S.paint);
    const models = ['coupe', 'truck', 'formula', 'van', 'buggy', 'wedge', 'muscle', 'specter', 'phantom'];
    const lanes = [-2.9, -.95, .95, 2.9];
    const names = ['You', 'Rex', 'Nova', 'Bolt'];
    const playerSt = loadoutStats();
    const playerBase = 17.5 + playerSt.speed * 1.02 + playerSt.accel * .14;
    for (let i = 0; i < 4; i++) {
      const isPlayer = i === 0;
      const modelId = isPlayer ? S.model : pick(models.filter(m => m !== S.model));
      const paint = isPlayer ? S.paint : paints[i % paints.length];
      const parts = isPlayer ? S.equippedParts : (Math.random() > .6 ? [pick(PARTS).id] : []);
      const modelDef = MODELS.find(m => m.id === modelId) || MODELS[0];
      const group = buildCar({ paint, model: modelId, wheels: isPlayer ? S.wheels : pick(WHEELS).id, parts, race: true }, { race: true });
      group.scale.setScalar(.74);
      // detach contact shadow to ground
      const sh = group.getObjectByName('contactShadow');
      let shadow = null;
      if (sh) { group.remove(sh); sh.scale.setScalar(1 / .74); sh.material.opacity = .7; this.scene.add(sh); shadow = sh; }
      this.scene.add(group);
      const aiGrip = isPlayer ? playerSt.grip : (5 + Math.random() * 4);
      const aiSpeed = isPlayer ? playerBase : playerBase * (0.94 + Math.random() * 0.055);
      const car = {
        idx: i, isPlayer, name: names[i], group, shadow,
        color: PAINTS.find(p => p.id === paint).css,
        model: modelDef, paint,
        t: 0, dist: 0, lateral: lanes[i], targetLane: lanes[i],
        maxSpeed: aiSpeed, speed: 0, accel: isPlayer ? (1.8 + playerSt.accel * .12) : (1.7 + Math.random() * .5),
        grip: aiGrip, lap: 1, finished: false, finishTime: 0,
        y: 0, pitch: 0, hop: 0, hopT: 0, looping: 0, loopT: 0, boost: 0, oil: 0,
        drift: 0, stun: 0, bumpCd: 0, laneTimer: 1 + Math.random() * 2, lastLap: 0,
        wheelSpin: 0, sparkSide: 0, progress: 0
      };
      this.cars.push(car);
    }
    this.player = this.cars[0];
    // grid start — player 3rd
    const order = [1, 2, 0, 3];
    order.forEach((carIdx, slot) => {
      const car = this.cars[carIdx];
      car.progress = -slot * .0055;
      car.t = (1 + car.progress) % 1;
      car.dist = car.progress * this.trackLength;
      car.targetLane = car.lateral = lanes[slot];
    });
    this.startPos = 3;
    this.pos = 3;
    this.scene.environment = this.scene.environment;
  },

  buildItems() {
    this.items = [];
    const rng = mulberry32(hashGrid(S.trackGrid) ^ 0xabcdef);
    const types = [
      ['boost', 3], ['oil', 2], ['bump', 2], ['cone', 5], ['coin', 8],
    ];
    let slot = 0;
    for (const [type, count] of types) {
      for (let i = 0; i < count; i++) {
        const t = (.1 + slot * .105 + rng() * .04) % .96;
        const lateral = (rng() * 2 - 1) * (this.roadW / 2 - 1.8);
        this.addItem(type, t, lateral);
        slot++;
      }
    }
    // Lava hazard flavor — extra cones
  },
  addItem(type, t, lateral) {
    const p = this.curve.getPointAt(t), tan = this.curve.getTangentAt(t);
    const n = new THREE.Vector3(tan.z, 0, -tan.x);
    const pos = p.clone().addScaledVector(n, lateral);
    let mesh = new THREE.Group();
    const glow = this.terrain.dust;
    if (type === 'coin') {
      const mat = new THREE.MeshPhysicalMaterial({ color: 0xffcf3d, metalness: 1, roughness: .18, clearcoat: 1 });
      const c = new THREE.Mesh(new THREE.CylinderGeometry(.42, .42, .09, 20), mat);
      c.rotation.z = Math.PI / 2; c.castShadow = true;
      const rim = new THREE.Mesh(new THREE.TorusGeometry(.42, .05, 8, 24), new THREE.MeshBasicMaterial({ color: 0xfff1a8 }));
      rim.rotation.y = Math.PI / 2;
      mesh.add(c, rim);
      mesh.position.set(pos.x, 1.0, pos.z);
    } else if (type === 'boost') {
      const mat = new THREE.MeshBasicMaterial({ color: 0x39e7ff, transparent: true, opacity: .72, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
      const plane = new THREE.Mesh(new THREE.PlaneGeometry(3.4, 3.8), mat);
      plane.rotation.x = -Math.PI / 2;
      mesh.add(plane);
      for (let i = 0; i < 2; i++) {
        const chev = new THREE.Mesh(new THREE.PlaneGeometry(2.2, .5), new THREE.MeshBasicMaterial({ color: 0xd6fbff, transparent: true, opacity: .8, side: THREE.DoubleSide }));
        chev.rotation.x = -Math.PI / 2; chev.position.set(0, .03, -.7 + i * 1.4);
        mesh.add(chev);
      }
      mesh.position.set(pos.x, .06, pos.z);
    } else if (type === 'oil') {
      const mat = new THREE.MeshPhysicalMaterial({ color: 0x08080c, metalness: .9, roughness: .08, transparent: true, opacity: .85, clearcoat: 1 });
      const plane = new THREE.Mesh(new THREE.CircleGeometry(1.7, 24), mat);
      plane.rotation.x = -Math.PI / 2; plane.scale.set(1, .7, 1);
      mesh.add(plane);
      mesh.position.set(pos.x, .05, pos.z);
    } else if (type === 'bump') {
      const mat = new THREE.MeshStandardMaterial({ color: 0xffc21a, roughness: .5 });
      const b = new THREE.Mesh(new THREE.BoxGeometry(2.8, .22, .5), mat);
      b.castShadow = true; mesh.add(b);
      const stripe = new THREE.Mesh(new THREE.BoxGeometry(2.82, .23, .12), new THREE.MeshStandardMaterial({ color: 0x181a1f }));
      stripe.position.z = .05; mesh.add(stripe);
      mesh.position.set(pos.x, .12, pos.z);
    } else if (type === 'cone') {
      const mat = new THREE.MeshStandardMaterial({ color: 0xff6a1f, roughness: .5 });
      const cone = new THREE.Mesh(new THREE.ConeGeometry(.34, 1.0, 16), mat);
      cone.position.y = .5; cone.castShadow = true;
      const band = new THREE.Mesh(new THREE.CylinderGeometry(.22, .26, .16, 16), new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: .4 }));
      band.position.y = .45;
      const base = new THREE.Mesh(new THREE.BoxGeometry(.72, .07, .72), new THREE.MeshStandardMaterial({ color: 0xe4571a }));
      base.position.y = .035;
      mesh.add(cone, band, base);
      mesh.position.set(pos.x, 0, pos.z);
    }
    mesh.traverse(o => { if (o.isMesh) o.castShadow = true; });
    mesh.rotation.y = Math.atan2(tan.x, tan.z);
    this.world.add(mesh);
    this.items.push({ type, t, lateral, mesh, pos: new THREE.Vector3(pos.x, 0, pos.z), active: true, phase: Math.random() * 6, baseY: mesh.position.y });
  },

  fitCamera() {
    const W = $('#raceStage').clientWidth || innerWidth;
    const H = $('#raceStage').clientHeight || innerHeight;
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    for (const p of this.curveSamples) { minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z); }
    const pad = 12;
    minX -= pad; maxX += pad; minZ -= pad; maxZ += pad;
    const cx = (minX + maxX) / 2, cz = (minZ + maxZ) / 2;
    const scale = Math.min(W / (maxX - minX), H / (maxZ - minZ)) * .94;
    this.mapScale = scale; this.mapC = { x: cx, z: cz };
    const hw = W / (2 * scale), hh = H / (2 * scale);
    this.ortho.left = -hw; this.ortho.right = hw; this.ortho.top = hh; this.ortho.bottom = -hh;
    this.ortho.updateProjectionMatrix();
    this.ortho.position.set(cx, 90, cz);
    this.ortho.lookAt(cx, 0, cz);
    this.bounds = { minX, maxX, minZ, maxZ };
  },
  setCam(mode) {
    this.camMode = mode;
    $$('.cam-btn').forEach(b => {
      const on = b.dataset.cam === mode;
      b.classList.toggle('bg-lime', on); b.classList.toggle('text-black', on); b.classList.toggle('text-slate-300', !on);
    });
    const full = mode === 'full';
    $('#race2d').style.opacity = full ? '1' : '0';
    if (this.world) this.world.visible = !full;
    if (this.shadowCatcher) this.shadowCatcher.visible = full;
    this.renderer.setClearColor(0x000000, full ? 0 : 1);
    if (this.scene) {
      this.scene.background = full ? null : (this.scene.userData.sky || null);
      this.scene.fog = full ? null : (this.scene.userData.fog || null);
    }
    if (this.cars) this.cars.forEach(c => { if (c.group) c.group.visible = true; });
    this.mapDirty = true;
    if (full) { this.fitCamera(); this.drawRace2D(); }
    Sfx.click();
  },
  drawRace2D() {
    const canvas = $('#race2d');
    const W = canvas.clientWidth, H = canvas.clientHeight;
    if (!W || !H || !this.bounds) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    if (canvas.width !== Math.round(W * dpr) || canvas.height !== Math.round(H * dpr)) {
      canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
    }
    const ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    const terrain = this.terrain;
    const g = ctx.createRadialGradient(W / 2, H / 2, 40, W / 2, H / 2, Math.max(W, H) * .7);
    g.addColorStop(0, new THREE.Color(terrain.bg).offsetHSL(0, 0, .04).getStyle());
    g.addColorStop(1, '#070a10');
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    const s = this.mapScale, cx = this.mapC.x, cz = this.mapC.z;
    const P = (x, z) => [W / 2 + (x - cx) * s, H / 2 + (z - cz) * s];
    // ground dots
    const rng = mulberry32(hashGrid(S.trackGrid) ^ 77);
    ctx.fillStyle = 'rgba(255,255,255,.14)';
    for (let i = 0; i < 80; i++) { const a = rng() * 7, r = rng() * 130; const [x, y] = P(Math.cos(a) * r, Math.sin(a) * r); if (x > 0 && x < W && y > 0 && y < H) ctx.fillRect(x, y, 1, 1); }
    // track path
    const pts = this.curveSamples;
    const path = () => {
      ctx.beginPath();
      pts.forEach((p, i) => { const [x, y] = P(p.x, p.z); if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y); });
      ctx.closePath();
    };
    ctx.lineJoin = 'round'; ctx.lineCap = 'round';
    path(); ctx.strokeStyle = 'rgba(0,0,0,.5)'; ctx.lineWidth = (this.roadW + 3.2) * s; ctx.stroke();
    path(); ctx.strokeStyle = '#33383f'; ctx.lineWidth = this.roadW * s; ctx.stroke();
    path(); ctx.strokeStyle = 'rgba(255,255,255,.55)'; ctx.lineWidth = Math.max(1, .16 * s); ctx.stroke();
    path(); ctx.strokeStyle = 'rgba(255,255,255,.3)'; ctx.lineWidth = this.roadW * s; ctx.setLineDash([6, 14]); ctx.stroke(); ctx.setLineDash([]);
    // start line
    const p0 = this.curve.getPointAt(0), tan = this.curve.getTangentAt(0);
    const n = new THREE.Vector3(tan.z, 0, -tan.x);
    for (let i = 0; i < 10; i++) {
      const off = -this.roadW / 2 + (i + .5) * this.roadW / 10;
      const pp = p0.clone().addScaledVector(n, off);
      const [x, y] = P(pp.x, pp.z);
      ctx.fillStyle = i % 2 ? '#f5f7fa' : '#15171c';
      ctx.fillRect(x - 3, y - 3, 6, 6);
    }
    // items dots
    for (const it of this.items) {
      if (!it.active) continue;
      const [x, y] = P(it.pos.x, it.pos.z);
      ctx.beginPath();
      if (it.type === 'coin') { ctx.fillStyle = '#ffd24f'; ctx.arc(x, y, 3.5, 0, 7); ctx.fill(); }
      else if (it.type === 'boost') { ctx.fillStyle = '#39e7ff'; ctx.fillRect(x - 4, y - 3, 8, 6); }
      else if (it.type === 'oil') { ctx.fillStyle = 'rgba(20,20,26,.9)'; ctx.arc(x, y, 4, 0, 7); ctx.fill(); }
      else if (it.type === 'cone') { ctx.fillStyle = '#ff7a1f'; ctx.beginPath(); ctx.moveTo(x, y - 4); ctx.lineTo(x + 3, y + 3); ctx.lineTo(x - 3, y + 3); ctx.fill(); }
      else { ctx.fillStyle = '#ffc21a'; ctx.fillRect(x - 3, y - 2, 6, 4); }
    }
    ctx.fillStyle = 'rgba(255,255,255,.55)'; ctx.font = '700 10px Inter, sans-serif'; ctx.textAlign = 'right';
    ctx.fillText('ORTHOGRAPHIC TRACK OVERLAY · 1:1', W - 12, H - 12);
  },

