--- index.html
+++ index.html
@@ -2055,8 +2055,723 @@
   Sfx.resume();
   Race.start({ stake, laps: 2, mode: 'quick', trackName: S.lastTrackName || 'Custom Circuit' });
 });

+/* ============================================================
+   RACE ENGINE
+   ============================================================ */
+function countTileTypes(grid) {
+  const out = { total: 0, curve: 0, jump: [], loop: [], bridge: 0, start: 0 };
+  for (let y = 0; y < 5; y++) for (let x = 0; x < 8; x++) {
+    const t = grid[y] && grid[y][x]; if (!t) continue;
+    out.total++;
+    if (t.part === 'curve') out.curve++;
+    if (t.part === 'jump') out.jump.push({ x, y });
+    if (t.part === 'loop') out.loop.push({ x, y });
+    if (t.part === 'bridge') out.bridge++;
+    if (t.part === 'start') out.start++;
+  }
+  return out;
+}
+function makeAsphaltTexture(base = '#24272d') {
+  const c = document.createElement('canvas'); c.width = c.height = 256;
+  const ctx = c.getContext('2d');
+  ctx.fillStyle = base; ctx.fillRect(0, 0, 256, 256);
+  for (let i = 0; i < 5000; i++) {
+    const v = 20 + Math.random() * 60;
+    ctx.fillStyle = `rgba(${v},${v + 2},${v + 6},${Math.random() * .3})`;
+    const s = Math.random() * 2 + .4;
+    ctx.fillRect(Math.random() * 256, Math.random() * 256, s, s);
+  }
+  for (let i = 0; i < 30; i++) {
+    ctx.strokeStyle = `rgba(255,255,255,${Math.random() * .035})`; ctx.lineWidth = Math.random() * 3 + .5;
+    ctx.beginPath(); ctx.moveTo(Math.random() * 256, Math.random() * 256); ctx.lineTo(Math.random() * 256, Math.random() * 256); ctx.stroke();
+  }
+  const tex = new THREE.CanvasTexture(c);
+  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
+  tex.repeat.set(1.4, 1);
+  tex.encoding = THREE.sRGBEncoding;
+  tex.anisotropy = 4;
+  return tex;
+}
+function makeGroundTexture(terrain) {
+  const c = document.createElement('canvas'); c.width = c.height = 256;
+  const ctx = c.getContext('2d');
+  ctx.fillStyle = terrain.bg; ctx.fillRect(0, 0, 256, 256);
+  const rng = mulberry32(terrain.bg.length * 999 + 7);
+  for (let i = 0; i < 900; i++) {
