input.oldString:
  ctx.fillStyle = 'rgba(255,255,255,.55)'; ctx.font = '700 10px Inter, sans-serif'; ctx.textAlign = 'right';
  ctx.fillText('ORTHOGRAPHIC TRACK OVERLAY · 1:1', W - 12, H - 12);
},

input.newString:
  ctx.fillStyle = 'rgba(255,255,255,.55)'; ctx.font = '700 10px Inter, sans-serif'; ctx.textAlign = 'right';
  ctx.fillText('ORTHOGRAPHIC TRACK OVERLAY · 1:1', W - 12, H - 12);
},

tick(dt) {
  if (!this.active || !this.renderer) return;
  if (this.finished) { this.renderScene(); return; }
  if (this.paused) { this.renderScene(); return; }
  if (this.countdown > 0) {
    this.countdown -= dt;
    this.updateCamera(dt, true);
    this.renderScene();
    this.updateHud();
    return;
  }
  this.elapsed += dt;
  this.updateCars(dt);
  this.updateItems(dt);
  this.updateParticles(dt);
  this.updateCamera(dt, false);
  this.updateHud();
  this.renderScene();
},

renderScene() {
  if (!this.scene || !this.renderer) return;
  if (this.camMode === 'full') {
    this.mapTimer = (this.mapTimer || 0) + 1;
    if (this.mapDirty || this.mapTimer % 30 === 0) { this.drawRace2D(); this.mapDirty = false; }
    this.renderer.render(this.scene, this.ortho);
  } else {
    this.renderer.render(this.scene, this.camera);
  }
},

updateCars(dt) {
  const L = this.trackLength;
  const lim = this.roadW / 2 - 1.1;
  const steerInput = (this.input.right ? 1 : 0) - (this.input.left ? 1 : 0);
  for (const car of this.cars) {
    if (car.finished) continue;
    const prevT = car.t;
    let steer = 0;
    if (car.isPlayer) {
      steer = steerInput;
      this.itemState.drift = lerp(this.itemState.drift, Math.abs(steer) > .1 ? 1 : 0, dt * 5);
    } else {
      car.laneTimer -= dt;
      if (car.laneTimer <= 0) {
        car.laneTimer = 1.6 + Math.random() * 2.4;
        car.targetLane = (Math.random() * 2 - 1) * lim * .82;
      }
      steer = clamp((car.targetLane - car.lateral) * .55 + Math.sin(this.elapsed * 1.3 + car.idx) * .18, -1, 1);
    }
    if (car.oil > 0) steer *= .35;
    car.oil = Math.max(0, car.oil - dt);
    car.boost = Math.max(0, car.boost - dt);
    car.stun = Math.max(0, car.stun - dt);
    car.bumpCd = Math.max(0, car.bumpCd - dt);
    car.lateral += steer * (4.2 + car.grip * .22) * dt;
    let wallHit = false;
    if (car.lateral > lim) { car.lateral = lim; wallHit = true; }
    if (car.lateral < -lim) { car.lateral = -lim; wallHit = true; }
    let targetSpeed = car.maxSpeed;
    if (car.boost > 0) targetSpeed *= 1.36;
    if (car.oil > 0) targetSpeed *= .68;
    if (car.stun > 0) targetSpeed *= .84;
    if (!car.isPlayer && this.player) {
      const gap = this.player.dist - car.dist;
      if (gap > L * .1) targetSpeed *= 1.055;
      else if (gap < -L * .08) targetSpeed *= .975;
    }
    car.speed = lerp(car.speed, targetSpeed, clamp(dt * car.accel * 1.5, 0, 1));
    if (wallHit) {
      car.speed *= (1 - dt * .7);
      const side = car.lateral > 0 ? 1 : -1;
      if (car.isPlayer && this.sparksCooldown <= 0) {
        this.sparksCooldown = .12;
        const wp = this.carWorldPos(car);
        const n = this.curve.getTangentAt(car.t);
        const right = new THREE.Vector3(n.z, 0, -n.x);
        this.spawnSparks(wp.clone().addScaledVector(right, side * 1.0), 0xc6ff3d, 5);
        car.speed *= .995;
        Sfx.noise(.05, .12, 2400, 2);
      }
    }
    car.speed = clamp(car.speed, 2, 62);
    car.dist += car.speed * dt;
    car.t = ((car.dist / L) % 1 + 1) % 1;
    car.wheelSpin += car.speed * dt * 1.1;
    // features crossed
    const span = ((car.t - prevT) + 1) % 1;
    for (const jt of this.features.jumps) {
      const dj = (jt - prevT + 1) % 1;
      if (dj > 0 && dj <= span && car.hopT <= 0) {
        car.hopT = .85;
        if (car.isPlayer) Sfx.jump();
        this.spawnSmoke(this.carWorldPos(car), 0xd8c7a0, 4);
      }
    }
    for (const lt of this.features.loops) {
      const dl = (lt - prevT + 1) % 1;
      if (dl > 0 && dl <= span && car.loopT <= 0) {
        car.loopT = 1.0;
        if (car.isPlayer) Sfx.boost();
      }
    }
    // hop / loop animation
    if (car.hopT > 0) {
      car.hopT = Math.max(0, car.hopT - dt);
      const p = 1 - car.hopT / .85;
      car.y = Math.sin(p * Math.PI) * 2.8;
      if (car.hopT === 0) car.y = 0;
    } else if (car.loopT > 0) {
      car.loopT = Math.max(0, car.loopT - dt);
      const p = 1 - car.loopT / 1.0;
      car.pitch = p * Math.PI * 2;
      car.y = Math.sin(p * Math.PI) * 2.2;
      if (car.loopT === 0) { car.pitch = 0; car.y = 0; }
    } else {
      car.y = lerp(car.y, 0, dt * 10);
      car.pitch = lerp(car.pitch, 0, dt * 6);
    }
    // lap crossing
    const completed = Math.floor(car.dist / L);
    if (completed > car.lastLap) {
      car.lastLap = completed;
      car.lap = Math.min(this.laps + 1, completed + 1);
      if (car.isPlayer && completed >= 1) {
        const lt = this.elapsed - this.lapStart;
        this.lapStart = this.elapsed;
        if (this.bestLap == null || lt < this.bestLap) { this.bestLap = lt; if (S.bestLap == null || lt < S.bestLap) { S.bestLap = lt; } }
        Sfx.lap();
        this.flash('rgba(198,255,61,.14)');
      }
      if (!car.isPlayer) this.spawnSmoke(this.carWorldPos(car), 0xffffff, 2);
      if (completed >= this.laps && !car.finished) {
        car.finished = true; car.finishTime = this.elapsed;
        car.dist = this.laps * L;
        car.lap = this.laps;
        if (car.isPlayer) { this.finishRace(); return; }
      }
    }
    // drift and pose
    const tan = this.curve.getTangentAt(car.t);
    const n = new THREE.Vector3(tan.z, 0, -tan.x);
    const p = this.curve.getPointAt(car.t);
    const wp = p.clone().addScaledVector(n, car.lateral);
    const yaw = Math.atan2(tan.x, tan.z);
    const driftTarget = car.isPlayer ? steer * .17 : steer * .07;
    car.drift = lerp(car.drift || 0, driftTarget, dt * 6);
    car.group.position.set(wp.x, car.y, wp.z);
    const oilWobble = car.oil > 0 ? Math.sin(this.elapsed * 22 + car.idx) * .5 : 0;
    const euler = new THREE.Euler(car.pitch, yaw + car.drift + oilWobble, -steer * .055, 'YXZ');
    car.group.quaternion.setFromEuler(euler);
    if (car.shadow) {
      car.shadow.position.set(wp.x, .025, wp.z);
      car.shadow.quaternion.setFromEuler(new THREE.Euler(-Math.PI / 2, yaw, 0, 'YXZ'));
      const shr = clamp(1 - car.y * .16, .45, 1);
      car.shadow.scale.set(shr, shr, shr);
      car.shadow.material.opacity = .72 * shr;
    }
    if (car.group.userData.wheels) {
      for (const w of car.group.userData.wheels.children) w.rotation.x = car.wheelSpin * (car.isPlayer ? 1 : .9);
    }
    // drift smoke
    if (car.isPlayer && Math.abs(steer) > .5 && car.speed > 12 && Math.random() < dt * 22) {
      this.spawnSmoke(wp.clone().addScaledVector(n, car.lateral > 0 ? 1 : -1).add(new THREE.Vector3(0, .2, 0)), this.terrain.dust, 1);
      this.itemState.drift = 1;
    }
    // boost flame
    if (car.boost > 0 && Math.random() < dt * 30) {
      const back = wp.clone().addScaledVector(n, 0).add(new THREE.Vector3(Math.sin(yaw) * -1.5, .45, Math.cos(yaw) * -1.5));
      this.spawnSparks(back, 0x39e7ff, 1);
    }
    car.progress = car.dist / L;
  }
  this.sparksCooldown = Math.max(0, this.sparksCooldown - dt);
  // car-to-car bumps
  for (let i = 0; i < this.cars.length; i++) for (let j = i + 1; j < this.cars.length; j++) {
    const a = this.cars[i], b = this.cars[j];
    const dd = a.dist - b.dist;
    if (Math.abs(dd) < 2.6 && Math.abs(a.lateral - b.lateral) < 1.45) {
      const push = a.lateral >= b.lateral ? 1 : -1;
      a.lateral = clamp(a.lateral + push * .035, -lim, lim);
      b.lateral = clamp(b.lateral - push * .035, -lim, lim);
      a.speed *= (1 - dt * 1.4); b.speed *= (1 - dt * 1.4);
      if ((a.isPlayer || b.isPlayer)) {
        const pc = a.isPlayer ? a : b;
        if (pc.bumpCd <= 0) {
          pc.bumpCd = .35;
          Sfx.bump();
          this.spawnSparks(this.carWorldPos(pc).add(new THREE.Vector3(0, .5, 0)), 0xffc46b, 8);
          this.shake = Math.max(this.shake, .35);
        }
      }
    }
  }
  // standings
  const sorted = this.cars.slice().sort((a, b) => b.dist - a.dist);
  this.pos = sorted.indexOf(this.player) + 1;
  this.standings = sorted;
},

carWorldPos(car) {
  const tan = this.curve.getTangentAt(car.t);
  const n = new THREE.Vector3(tan.z, 0, -tan.x);
  return this.curve.getPointAt(car.t).addScaledVector(n, car.lateral).setY(car.y || 0);
},

updateItems(dt) {
  const player = this.player;
  for (const it of this.items) {
    if (!it.active) continue;
    it.phase += dt;
    if (it.type === 'coin') {
      it.mesh.rotation.y += dt * 2.6;
      it.mesh.position.y = 1.0 + Math.sin(it.phase * 2.4) * .16;
    } else if (it.type === 'boost') {
      it.mesh.children[0].material.opacity = .55 + Math.sin(it.phase * 5) * .25;
    } else if (it.type === 'cone') {
      it.mesh.rotation.y += Math.sin(it.phase) * .002;
    }
    if (!player || player.finished) continue;
    const wp = this.carWorldPos(player);
    const magnet = partEquipped('magnet') || S.equippedParts.includes('magnet');
    const radius = it.type === 'coin' && magnet ? 4.6 : 2.35;
    const dx = wp.x - it.pos.x, dz = wp.z - it.pos.z;
    if (dx * dx + dz * dz < radius * radius) {
      it.active = false;
      if (it.type === 'coin') {
        it.mesh.visible = false;
        const bonus = 8 + Math.round(Math.random() * 7);
        S.cash += bonus; Sfx.coin();
        this.itemState.lastCoin = bonus;
        this.flash('rgba(255,210,79,.12)');
        this.updateHud(true);
      } else if (it.type === 'boost') {
        it.mesh.visible = false;
        player.boost = 1.9; Sfx.boost(); this.flash('rgba(57,231,255,.15)');
      } else if (it.type === 'oil') {
        player.oil = 1.6; player.speed *= .8; Sfx.noise(.25, .2, 240); this.flash('rgba(255,255,255,.08)');
        this.spawnSmoke(wp, 0x2a2a34, 6);
      } else if (it.type === 'bump') {
        player.speed *= .78; player.hopT = .5; Sfx.bump(); this.shake = .5;
        this.spawnSparks(wp.clone().add(new THREE.Vector3(0, .2, 0)), 0xffc21a, 6);
      } else if (it.type === 'cone') {
        player.speed *= .86; Sfx.bump(); this.shake = .35;
        this.spawnSparks(wp.clone().add(new THREE.Vector3(0, .25, 0)), 0xff7a1f, 7);
        it.mesh.rotation.z = 1.2; it.mesh.position.y = -.1;
        setTimeout(() => { if (it.mesh) { it.mesh.rotation.z = 0; it.mesh.position.y = 0; } }, 900);
        it.active = true; // cones remain but no more effects for 1.2s
        it.cool = performance.now() + 1200;
      }
      if (it.type !== 'cone') it.cool = 0;
    }
  }
  // cooldown cones: if cool and time passed, allow again
  for (const it of this.items) {
    if (it.active && it.cool) {
      if (performance.now() > it.cool) { it.cool = 0; it.mesh.position.y = 0; it.mesh.rotation.z = 0; }
      else it.active = false, setTimeout(() => { it.active = true; }, 20);
    }
  }
},

spawnSmoke(pos, color, n) {
  if (!this.scene) return;
  for (let i = 0; i < n; i++) {
    const mat = new THREE.SpriteMaterial({ map: getSmokeTex(), color, transparent: true, opacity: .45, depthWrite: false });
    const sp = new THREE.Sprite(mat);
    sp.position.copy(pos);
    sp.position.x += (Math.random() - .5) * .8;
    sp.position.z += (Math.random() - .5) * .8;
    sp.position.y += .2 + Math.random() * .3;
    sp.scale.setScalar(.5 + Math.random() * .7);
    this.scene.add(sp);
    this.particles.push({ sp, life: 0, max: .7 + Math.random() * .6, vel: new THREE.Vector3((Math.random() - .5) * .7, .8 + Math.random() * .6, (Math.random() - .5) * .7), grow: 1.4 });
  }
},
spawnSparks(pos, color, n) {
  if (!this.scene) return;
  for (let i = 0; i < n; i++) {
    const mat = new THREE.SpriteMaterial({ map: getSparkTex(), color, transparent: true, opacity: .95, depthWrite: false, blending: THREE.AdditiveBlending });
    const sp = new THREE.Sprite(mat);
    sp.position.copy(pos);
    sp.scale.setScalar(.12 + Math.random() * .2);
    this.scene.add(sp);
    this.particles.push({ sp, life: 0, max: .28 + Math.random() * .25, vel: new THREE.Vector3((Math.random() - .5) * 8, Math.random() * 5 + 1, (Math.random() - .5) * 8), grow: .3, spark: true });
  }
},
updateParticles(dt) {
  for (let i = this.particles.length - 1; i >= 0; i--) {
    const p = this.particles[i];
    p.life += dt;
    if (p.life >= p.max) { this.scene.remove(p.sp); p.sp.material.dispose(); this.particles.splice(i, 1); continue; }
    p.sp.position.addScaledVector(p.vel, dt);
    if (p.spark) { p.vel.y -= 12 * dt; p.sp.material.opacity = 1 - p.life / p.max; }
    else { p.vel.multiplyScalar(1 - dt * 1.6); p.sp.scale.addScalar(dt * p.grow); p.sp.material.opacity = .42 * (1 - p.life / p.max); }
  }
  if (this.dust) {
    this.dust.rotation.y += dt * .012;
    this.dust.position.y = Math.sin(this.elapsed * .3) * .2;
  }
},

updateCamera(dt, countdown) {
  if (!this.player) return;
  if (this.camMode === 'full') { this.updateCameraButtons(); return; }
  const car = this.player;
  const tan = this.curve.getTangentAt(car.t);
  const fwd = new THREE.Vector3(tan.x, 0, tan.z).normalize();
  const p = car.group.position;
  let back = 6.4, height = 3.0, look = 4.2;
  if (this.camMode === 'wide') { back = 13.5; height = 7.2; look = 7.5; }
  if (this.camMode === 'chase') { back = 4.7; height = 1.85; look = 5.5; }
  const target = p.clone().addScaledVector(fwd, -back).setY(p.y + height);
  const lookTarget = p.clone().addScaledVector(fwd, look).setY(p.y + .95);
  if (countdown) {
    this.camPos.copy(target); this.camLook.copy(lookTarget);
  } else {
    const k = 1 - Math.exp(-dt * (this.camMode === 'chase' ? 11 : 7));
    this.camPos.lerp(target, k);
    this.camLook.lerp(lookTarget, 1 - Math.exp(-dt * 10));
  }
  this.shake = Math.max(0, this.shake - dt * 2.2);
  const sx = (Math.random() - .5) * this.shake * 1.2;
  const sy = (Math.random() - .5) * this.shake * 1.2;
  this.camera.position.set(this.camPos.x + sx, Math.max(.4, this.camPos.y + sy), this.camPos.z);
  this.camera.up.set(0, 1, 0);
  this.camera.lookAt(this.camLook.x, this.camLook.y, this.camLook.z);
  this.camera.fov = this.camMode === 'wide' ? 52 : this.camMode === 'chase' ? 64 : 58;
  this.camera.updateProjectionMatrix();
},
updateCameraButtons() {
  if (this._camBtnLoaded) return;
  this._camBtnLoaded = true;
  $$('.cam-btn').forEach(b => b.addEventListener('click', () => this.setCam(b.dataset.cam)));
},

updateHud(force) {
  const curLapTime = this.started ? Math.max(0, this.elapsed - this.lapStart) : 0;
  $('#raceTimer').textContent = fmtTime(curLapTime);
  $('#raceLap').textContent = Math.min(this.player.lap, this.laps);
  $('#raceLaps').textContent = this.laps;
  $('#raceBest').textContent = 'Best ' + fmtTime(this.bestLap);
  $('#raceCash').textContent = Math.round(S.cash).toLocaleString('en-US');
  $('#racePos').textContent = this.pos;
  const st = this.itemState;
  let status = 'Ready';
  if (st.boost > 0) status = 'BOOST'; else if (this.player && this.player.boost > 0) status = 'BOOST';
  else if (this.player && this.player.oil > 0) status = 'OIL SLICK';
  else if (Math.abs((this.player && this.player.drift) || 0) > .08) status = 'DRIFT';
  else if (st.lastCoin) status = `+$${st.lastCoin} COIN`;
  const el = $('#raceItemStatus');
  if (el) { el.textContent = status; el.className = status === 'Ready' ? 'text-slate-300' : status === 'DRIFT' ? 'text-magentax' : status.includes('COIN') ? 'text-amber-300' : 'text-cyanx pulse-dot'; }
  const now = performance.now();
  if (force || now - this.lbTimer > 160) {
    this.lbTimer = now;
    const sorted = this.standings || this.cars.slice().sort((a, b) => b.dist - a.dist);
    const sig = sorted.map(c => c.idx + (c.isPlayer ? 'P' : '')).join(',') + '|' + sorted.map(c => c.lap).join(',');
    const wrap = $('#raceLeaderboard');
    if (sig !== this.lastLb) {
      this.lastLb = sig;
      wrap.innerHTML = sorted.map((c, i) => {
        const pos = i + 1;
        const medal = pos === 1 ? '#c6ff3d' : pos === 2 ? '#cfd8e4' : pos === 3 ? '#e2a06a' : '#6f7a8c';
        return `<div class="lb-item relative px-1.5 py-1 ${c.isPlayer ? '!border-lime/50' : ''}" data-lb="${c.idx}">
          <div class="flex items-center gap-1.5">
            <span class="font-display w-3 text-[9px] font-black" style="color:${medal}">${pos}</span>
            <span class="h-1.5 w-1.5 shrink-0 rounded-full" style="background:${c.color}"></span>
            <span class="min-w-0 flex-1 truncate text-[9.5px] font-bold ${c.isPlayer ? 'text-lime' : 'text-slate-200'}">${c.name}</span>
            <span class="text-[8px] text-slate-500">L${Math.min(c.lap, this.laps)}</span>
          </div>
          <div class="mt-1 h-[3px] overflow-hidden rounded-full bg-white/10"><i class="block h-full rounded-full" style="width:${clamp((c.dist / (this.laps * this.trackLength)) * 100, 2, 100)}%;background:${c.color}"></i></div>
        </div>`;
      }).join('');
    } else {
      sorted.forEach(c => {
        const row = wrap.querySelector(`[data-lb="${c.idx}"] i`);
        if (row) row.style.width = clamp((c.dist / (this.laps * this.trackLength)) * 100, 2, 100) + '%';
      });
    }
  }
},

flash(color) {
  const f = $('#raceFlash');
  if (!f) return;
  f.style.transition = 'none'; f.style.background = color; f.style.opacity = '1';
  requestAnimationFrame(() => { f.style.transition = 'opacity .45s'; f.style.opacity = '0'; });
},

togglePause(force) {
  if (!this.active || this.finished) return;
  this.paused = force !== undefined ? force : !this.paused;
  const menu = $('#pauseMenu');
  menu.classList.toggle('hidden', !this.paused);
  menu.classList.toggle('flex', this.paused);
  if (this.paused) { this.input.left = false; this.input.right = false; }
},

finishRace() {
  if (this.finished) return;
  this.finished = true;
  this.player.finished = true;
  const place = 1 + this.cars.filter(c => c !== this.player && c.dist > this.player.dist).length;
  this.pos = place;
  const result = this.applyRewards(place);
  this.result = result;
  this.updateHud(true);
  if (place === 1) Sfx.win(); else Sfx.lose();
  setTimeout(() => this.showResults(result), 750);
},

applyRewards(place) {
  const wins = place === 1;
  const rewards = [];
  let cash = 0;
  // stake
  if (this.stake > 0) {
    if (place === 1) { cash += this.stake * 2; rewards.push({ icon: '🏁', label: `1st place — stake doubled (${fmt$(this.stake * 2)})`, cls: 'text-lime' }); }
    else if (place === 2) { cash += this.stake; rewards.push({ icon: '🥈', label: `2nd place — stake returned (${fmt$(this.stake)})`, cls: 'text-slate-200' }); }
    else rewards.push({ icon: '💸', label: 'Stake lost', cls: 'text-rose-300' });
  }
  // base cash
  const base = Math.round(rand(25, 140));
  cash += base;
  rewards.push({ icon: '💵', label: `Race purse +${fmt$(base)}`, cls: 'text-amber-300' });
  let jackpot = false;
  if (Math.random() < 1 / 15) { cash += 250; jackpot = true; rewards.push({ icon: '🎰', label: 'JACKPOT! +$250', cls: 'text-amber-300 font-black' }); Sfx.key(); }
  // part drop on win
  if (wins && Math.random() < 1 / 6) {
    const owned = new Set(S.ownedParts);
    const candidates = PARTS.filter(p => !owned.has(p.id));
    if (candidates.length) {
      const p = pick(candidates);
      S.ownedParts.push(p.id);
      rewards.push({ icon: p.icon, label: `Part drop: ${p.name} unlocked!`, cls: 'text-magentax' });
      Sfx.key();
    } else {
      cash += 120;
      rewards.push({ icon: '🧰', label: 'All parts owned — +$120 bonus', cls: 'text-amber-300' });
    }
  }
  // boss key 1/400 any race
  if (Math.random() < 1 / 400) {
    S.bossKeys++;
    rewards.push({ icon: '🗝️', label: 'RARE! Boss Key +1', cls: 'text-amber-300' });
    Sfx.key();
  }
  // blue key boss only 1/800
  const isBoss = this.storyCtx && this.storyCtx.type === 'boss';
  if (isBoss && wins && Math.random() < 1 / 800) {
    S.blueKeys++;
    rewards.push({ icon: '🔹', label: 'ULTRA RARE! Blue Key +1', cls: 'text-sky-300' });
    Sfx.key();
  }
  // story progression
  if (this.storyCtx) {
    const d = this.storyCtx.district;
    if (this.storyCtx.type === 'guard' && wins) {
      const cur = S.story.guards[d] || 0;
      const max = DISTRICTS[d - 1].guards;
      if (cur < max) {
        S.story.guards[d] = cur + 1;
        S.bossKeys++;
        rewards.push({ icon: '🗝️', label: `Guard beaten! Boss Key +1 (${S.bossKeys})`, cls: 'text-amber-300' });
      } else {
        rewards.push({ icon: '✅', label: 'Guard rematch cleared', cls: 'text-slate-300' });
      }
    }
    if (this.storyCtx.type === 'boss' && wins) {
      if (!S.story.bosses.includes(d)) { S.story.bosses.push(d); S.story.bosses.sort(); }
      rewards.push({ icon: '🏆', label: `District ${d} Boss defeated — trophy earned!`, cls: 'text-amber-300 font-black' });
    }
  }
  S.story.races++;
  if (wins) S.story.wins++;
  S.cash += cash;
  save(true);
  return { place, cash, rewards, jackpot, win: wins, time: this.elapsed, best: this.bestLap, startPos: this.startPos, district: this.storyCtx && this.storyCtx.district };
},

showResults(r) {
  $('#pauseMenu').classList.add('hidden'); $('#pauseMenu').classList.remove('flex');
  $('#resultPlace').innerHTML = r.place + `<span class="text-lg text-slate-500">${ordinal(r.place)}</span>`;
  const subs = ['', 'Flawless driving. The streets remember.', 'So close — the lead was right there.', 'A hard-earned podium step.', 'The pack got away. Again.'];
  $('#resultSub').textContent = subs[r.place] || 'Race complete.';
  $('#resultKicker').textContent = this.storyCtx ? (this.storyCtx.type === 'boss' ? 'BOSS BATTLE COMPLETE' : 'STORY QUALIFIER COMPLETE') : 'RACE COMPLETE';
  $('#resultTime').textContent = fmtTime(r.time);
  $('#resultBest').textContent = fmtTime(r.best);
  $('#resultEarned').textContent = fmt$(r.cash);
  $('#resultRewards').innerHTML = r.rewards.map(x => `<div class="flex items-center gap-2 rounded-lg border border-white/[.06] bg-white/[.025] px-2.5 py-1.5 text-[10.5px] ${x.cls || 'text-slate-300'}"><span>${x.icon}</span><span>${x.label}</span></div>`).join('');
  const climb = $('#climbWrap');
  if (r.place < r.startPos) {
    climb.classList.remove('hidden');
    const bars = [{ label: 'START', pos: r.startPos }, { label: 'FINISH', pos: r.place }];
    $('#climbChart').innerHTML = bars.map(b => `<div class="flex flex-col items-center gap-1 h-full justify-end">
      <div class="text-[9px] font-bold ${b.label === 'FINISH' ? 'text-lime' : 'text-slate-400'}">P${b.pos}</div>
      <div class="bar-climb" style="height:${(5 - b.pos) / 4 * 56}px;${b.label === 'START' ? 'background:linear-gradient(180deg,#7b8799,#3e4654);' : ''}"></div>
      <div class="text-[7.5px] uppercase tracking-widest text-slate-500">${b.label}</div>
    </div>`).join('');
  } else {
    climb.classList.add('hidden');
  }
  const storyBtn = $('#resultsStoryBtn');
  if (this.storyCtx) storyBtn.classList.remove('hidden'); else storyBtn.classList.add('hidden');
  const bp = $('#bossProgress');
  if (this.storyCtx) {
    bp.classList.remove('hidden');
    const d = this.storyCtx.district;
    const dist = DISTRICTS[d - 1];
    if (this.storyCtx.type === 'guard') {
      const done = S.story.guards[d] || 0;
      bp.textContent = done >= dist.guards ? `All ${dist.guards} guards cleared. The ${dist.bossName} awaits.` : `${done} / ${dist.guards} guards beaten · collect 4 Boss Keys to challenge ${dist.bossName}.`;
    } else {
      bp.textContent = r.place === 1 ? `🏆 ${dist.bossName} defeated!` : `The ${dist.bossName} escaped. Replay when you're ready.`;
    }
  } else bp.classList.add('hidden');
  $('#raceAgainBtn').onclick = () => this.start(this.opts);
  $('#resultsMenuBtn').onclick = () => this.quit();
  storyBtn.onclick = () => { this.quit(true); };
  $('#raceResults').classList.remove('hidden');
  this.updateHud(true);
},

quit(returnStory) {
  this.active = false; this.finished = false; this.paused = false;
  $('#raceOverlay').classList.add('hidden');
  $('#raceResults').classList.add('hidden');
  document.body.style.overflow = '';
  this.input.left = this.input.right = false;
  if (this.dust) this.dust = null;
  if (returnStory || this.mode === 'story') {
    setTab('story');
    if (returnStory) Hub.open();
    renderStoryPage();
  }
  save();
},

files.patch:
Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -2769,9 +2769,548 @@
     ctx.fillStyle = 'rgba(255,255,255,.55)'; ctx.font = '700 10px Inter, sans-serif'; ctx.textAlign = 'right';
     ctx.fillText('ORTHOGRAPHIC TRACK OVERLAY · 1:1', W - 12, H - 12);
   },

+  tick(dt) {
+    if (!this.active || !this.renderer) return;
+    if (this.finished) { this.renderScene(); return; }
+    if (this.paused) { this.renderScene(); return; }
+    if (this.countdown > 0) {
+      this.countdown -= dt;
+      this.updateCamera(dt, true);
+      this.renderScene();
+      this.updateHud();
+      return;
+    }
+    this.elapsed += dt;
+    this.updateCars(dt);
+    this.updateItems(dt);
+    this.updateParticles(dt);
+    this.updateCamera(dt, false);
+    this.updateHud();
+    this.renderScene();
+  },

+  renderScene() {
+    if (!this.scene || !this.renderer) return;
+    if (this.camMode === 'full') {
+      this.mapTimer = (this.mapTimer || 0) + 1;
+      if (this.mapDirty || this.mapTimer % 30 === 0) { this.drawRace2D(); this.mapDirty = false; }
+      this.renderer.render(this.scene, this.ortho);
+    } else {
+      this.renderer.render(this.scene, this.camera);
+    }
+  },

+  updateCars(dt) {
+    const L = this.trackLength;
+    const lim = this.roadW / 2 - 1.1;
+    const steerInput = (this.input.right ? 1 : 0) - (this.input.left ? 1 : 0);
+    for (const car of this.cars) {
+      if (car.finished) continue;
+      const prevT = car.t;
+      let steer = 0;
+      if (car.isPlayer) {
+        steer = steerInput;
+        this.itemState.drift = lerp(this.itemState.drift, Math.abs(steer) > .1 ? 1 : 0, dt * 5);
+      } else {
+        car.laneTimer -= dt;
+        if (car.laneTimer <= 0) {
+          car.laneTimer = 1.6 + Math.random() * 2.4;
+          car.targetLane = (Math.random() * 2 - 1) * lim * .82;
+        }
+        steer = clamp((car.targetLane - car.lateral) * .55 + Math.sin(this.elapsed * 1.3 + car.idx) * .18, -1, 1);
+      }
+      if (car.oil > 0) steer *= .35;
+      car.oil = Math.max(0, car.oil - dt);
+      car.boost = Math.max(0, car.boost - dt);
+      car.stun = Math.max(0, car.stun - dt);
+      car.bumpCd = Math.max(0, car.bumpCd - dt);
+      car.lateral += steer * (4.2 + car.grip * .22) * dt;
+      let wallHit = false;
+      if (car.lateral > lim) { car.lateral = lim; wallHit = true; }
+      if (car.lateral < -lim) { car.lateral = -lim; wallHit = true; }
+      let targetSpeed = car.maxSpeed;
+      if (car.boost > 0) targetSpeed *= 1.36;
+      if (car.oil > 0) targetSpeed *= .68;
+      if (car.stun > 0) targetSpeed *= .84;
+      if (!car.isPlayer && this.player) {
+        const gap = this.player.dist - car.dist;
+        if (gap > L * .1) targetSpeed *= 1.055;
+        else if (gap < -L * .08) targetSpeed *= .975;
+      }
+      car.speed = lerp(car.speed, targetSpeed, clamp(dt * car.accel * 1.5, 0, 1));
+      if (wallHit) {
+        car.speed *= (1 - dt * .7);
+        const side = car.lateral > 0 ? 1 : -1;
+        if (car.isPlayer && this.sparksCooldown <= 0) {
+          this.sparksCooldown = .12;
+          const wp = this.carWorldPos(car);
+          const n = this.curve.getTangentAt(car.t);
+          const right = new THREE.Vector3(n.z, 0, -n.x);
+          this.spawnSparks(wp.clone().addScaledVector(right, side * 1.0), 0xc6ff3d, 5);
+          car.speed *= .995;
+          Sfx.noise(.05, .12, 2400, 2);
+        }
+      }
+      car.speed = clamp(car.speed, 2, 62);
+      car.dist += car.speed * dt;
+      car.t = ((car.dist / L) % 1 + 1) % 1;
+      car.wheelSpin += car.speed * dt * 1.1;
+      // features crossed
+      const span = ((car.t - prevT) + 1) % 1;
+      for (const jt of this.features.jumps) {
+        const dj = (jt - prevT + 1) % 1;
+        if (dj > 0 && dj <= span && car.hopT <= 0) {
+          car.hopT = .85;
+          if (car.isPlayer) Sfx.jump();
+          this.spawnSmoke(this.carWorldPos(car), 0xd8c7a0, 4);
+        }
+      }
+      for (const lt of this.features.loops) {
+        const dl = (lt - prevT + 1) % 1;
+        if (dl > 0 && dl <= span && car.loopT <= 0) {
+          car.loopT = 1.0;
+          if (car.isPlayer) Sfx.boost();
+        }
+      }
+      // hop / loop animation
+      if (car.hopT > 0) {
+        car.hopT = Math.max(0, car.hopT - dt);
+        const p = 1 - car.hopT / .85;
+        car.y = Math.sin(p * Math.PI) * 2.8;
+        if (car.hopT === 0) car.y = 0;
+      } else if (car.loopT > 0) {
+        car.loopT = Math.max(0, car.loopT - dt);
+        const p = 1 - car.loopT / 1.0;
+        car.pitch = p * Math.PI * 2;
+        car.y = Math.sin(p * Math.PI) * 2.2;
+        if (car.loopT === 0) { car.pitch = 0; car.y = 0; }
+      } else {
+        car.y = lerp(car.y, 0, dt * 10);
+        car.pitch = lerp(car.pitch, 0, dt * 6);
+      }
+      // lap crossing
+      const completed = Math.floor(car.dist / L);
+      if (completed > car.lastLap) {
+        car.lastLap = completed;
+        car.lap = Math.min(this.laps + 1, completed + 1);
+        if (car.isPlayer && completed >= 1) {
+          const lt = this.elapsed - this.lapStart;
+          this.lapStart = this.elapsed;
+          if (this.bestLap == null || lt < this.bestLap) { this.bestLap = lt; if (S.bestLap == null || lt < S.bestLap) { S.bestLap = lt; } }
+          Sfx.lap();
+          this.flash('rgba(198,255,61,.14)');
+        }
+        if (!car.isPlayer) this.spawnSmoke(this.carWorldPos(car), 0xffffff, 2);
+        if (completed >= this.laps && !car.finished) {
+          car.finished = true; car.finishTime = this.elapsed;
+          car.dist = this.laps * L;
+          car.lap = this.laps;
+          if (car.isPlayer) { this.finishRace(); return; }
+        }
+      }
+      // drift and pose
+      const tan = this.curve.getTangentAt(car.t);
+      const n = new THREE.Vector3(tan.z, 0, -tan.x);
+      const p = this.curve.getPointAt(car.t);
+      const wp = p.clone().addScaledVector(n, car.lateral);
+      const yaw = Math.atan2(tan.x, tan.z);
+      const driftTarget = car.isPlayer ? steer * .17 : steer * .07;
+      car.drift = lerp(car.drift || 0, driftTarget, dt * 6);
+      car.group.position.set(wp.x, car.y, wp.z);
+      const oilWobble = car.oil > 0 ? Math.sin(this.elapsed * 22 + car.idx) * .5 : 0;
+      const euler = new THREE.Euler(car.pitch, yaw + car.drift + oilWobble, -steer * .055, 'YXZ');
+      car.group.quaternion.setFromEuler(euler);
+      if (car.shadow) {
+        car.shadow.position.set(wp.x, .025, wp.z);
+        car.shadow.quaternion.setFromEuler(new THREE.Euler(-Math.PI / 2, yaw, 0, 'YXZ'));
+        const shr = clamp(1 - car.y * .16, .45, 1);
+        car.shadow.scale.set(shr, shr, shr);
+        car.shadow.material.opacity = .72 * shr;
+      }
+      if (car.group.userData.wheels) {
+        for (const w of car.group.userData.wheels.children) w.rotation.x = car.wheelSpin * (car.isPlayer ? 1 : .9);
+      }
+      // drift smoke
+      if (car.isPlayer && Math.abs(steer) > .5 && car.speed > 12 && Math.random() < dt * 22) {
+        this.spawnSmoke(wp.clone().addScaledVector(n, car.lateral > 0 ? 1 : -1).add(new THREE.Vector3(0, .2, 0)), this.terrain.dust, 1);
+        this.itemState.drift = 1;
+      }
+      // boost flame
+      if (car.boost > 0 && Math.random() < dt * 30) {
+        const back = wp.clone().addScaledVector(n, 0).add(new THREE.Vector3(Math.sin(yaw) * -1.5, .45, Math.cos(yaw) * -1.5));
+        this.spawnSparks(back, 0x39e7ff, 1);
+      }
+      car.progress = car.dist / L;
+    }
+    this.sparksCooldown = Math.max(0, this.sparksCooldown - dt);
+    // car-to-car bumps
+    for (let i = 0; i < this.cars.length; i++) for (let j = i + 1; j < this.cars.length; j++) {
+      const a = this.cars[i], b = this.cars[j];
+      const dd = a.dist - b.dist;
+      if (Math.abs(dd) < 2.6 && Math.abs(a.lateral - b.lateral) < 1.45) {
+        const push = a.lateral >= b.lateral ? 1 : -1;
+        a.lateral = clamp(a.lateral + push * .035, -lim, lim);
+        b.lateral = clamp(b.lateral - push * .035, -lim, lim);
+        a.speed *= (1 - dt * 1.4); b.speed *= (1 - dt * 1.4);
+        if ((a.isPlayer || b.isPlayer)) {
+          const pc = a.isPlayer ? a : b;
+          if (pc.bumpCd <= 0) {
+            pc.bumpCd = .35;
+            Sfx.bump();
+            this.spawnSparks(this.carWorldPos(pc).add(new THREE.Vector3(0, .5, 0)), 0xffc46b, 8);
+            this.shake = Math.max(this.shake, .35);
+          }
+        }
+      }
+    }
+    // standings
+    const sorted = this.cars.slice().sort((a, b) => b.dist - a.dist);
+    this.pos = sorted.indexOf(this.player) + 1;
+    this.standings = sorted;
+  },
+
+  carWorldPos(car) {
+    const tan = this.curve.getTangentAt(car.t);
+    const n = new THREE.Vector3(tan.z, 0, -tan.x);
+    return this.curve.getPointAt(car.t).addScaledVector(n, car.lateral).setY(car.y || 0);
+  },
+
+  updateItems(dt) {
+    const player = this.player;
+    for (const it of this.items) {
+      if (!it.active) continue;
+      it.phase += dt;
+      if (it.type === 'coin') {
+        it.mesh.rotation.y += dt * 2.6;
+        it.mesh.position.y = 1.0 + Math.sin(it.phase * 2.4) * .16;
+      } else if (it.type === 'boost') {
+        it.mesh.children[0].material.opacity = .55 + Math.sin(it.phase * 5) * .25;
+      } else if (it.type === 'cone') {
+        it.mesh.rotation.y += Math.sin(it.phase) * .002;
+      }
+      if (!player || player.finished) continue;
+      const wp = this.carWorldPos(player);
+      const magnet = partEquipped('magnet') || S.equippedParts.includes('magnet');
+      const radius = it.type === 'coin' && magnet ? 4.6 : 2.35;
+      const dx = wp.x - it.pos.x, dz = wp.z - it.pos.z;
+      if (dx * dx + dz * dz < radius * radius) {
+        it.active = false;
+        if (it.type === 'coin') {
+          it.mesh.visible = false;
+          const bonus = 8 + Math.round(Math.random() * 7);
+          S.cash += bonus; Sfx.coin();
+          this.itemState.lastCoin = bonus;
+          this.flash('rgba(255,210,79,.12)');
+          this.updateHud(true);
+        } else if (it.type === 'boost') {
+          it.mesh.visible = false;
+          player.boost = 1.9; Sfx.boost(); this.flash('rgba(57,231,255,.15)');
+        } else if (it.type === 'oil') {
+          player.oil = 1.6; player.speed *= .8; Sfx.noise(.25, .2, 240); this.flash('rgba(255,255,255,.08)');
+          this.spawnSmoke(wp, 0x2a2a34, 6);
+        } else if (it.type === 'bump') {
+          player.speed *= .78; player.hopT = .5; Sfx.bump(); this.shake = .5;
+          this.spawnSparks(wp.clone().add(new THREE.Vector3(0, .2, 0)), 0xffc21a, 6);
+        } else if (it.type === 'cone') {
+          player.speed *= .86; Sfx.bump(); this.shake = .35;
+          this.spawnSparks(wp.clone().add(new THREE.Vector3(0, .25, 0)), 0xff7a1f, 7);
+          it.mesh.rotation.z = 1.2; it.mesh.position.y = -.1;
+          setTimeout(() => { if (it.mesh) { it.mesh.rotation.z = 0; it.mesh.position.y = 0; } }, 900);
+          it.active = true; // cones remain but no more effects for 1.2s
+          it.cool = performance.now() + 1200;
+        }
+        if (it.type !== 'cone') it.cool = 0;
+      }
+    }
+    // cooldown cones: if cool and time passed, allow again
+    for (const it of this.items) {
+      if (it.active && it.cool) {
+        if (performance.now() > it.cool) { it.cool = 0; it.mesh.position.y = 0; it.mesh.rotation.z = 0; }
+        else it.active = false, setTimeout(() => { it.active = true; }, 20);
+      }
+    }
+  },
+
+  spawnSmoke(pos, color, n) {
+    if (!this.scene) return;
+    for (let i = 0; i < n; i++) {
+      const mat = new THREE.SpriteMaterial({ map: getSmokeTex(), color, transparent: true, opacity: .45, depthWrite: false });
+      const sp = new THREE.Sprite(mat);
+      sp.position.copy(pos);
+      sp.position.x += (Math.random() - .5) * .8;
+      sp.position.z += (Math.random() - .5) * .8;
+      sp.position.y += .2 + Math.random() * .3;
+      sp.scale.setScalar(.5 + Math.random() * .7);
+      this.scene.add(sp);
+      this.particles.push({ sp, life: 0, max: .7 + Math.random() * .6, vel: new THREE.Vector3((Math.random() - .5) * .7, .8 + Math.random() * .6, (Math.random() - .5) * .7), grow: 1.4 });
+    }
+  },
+  spawnSparks(pos, color, n) {
+    if (!this.scene) return;
+    for (let i = 0; i < n; i++) {
+      const mat = new THREE.SpriteMaterial({ map: getSparkTex(), color, transparent: true, opacity: .95, depthWrite: false, blending: THREE.AdditiveBlending });
+      const sp = new THREE.Sprite(mat);
+      sp.position.copy(pos);
+      sp.scale.setScalar(.12 + Math.random() * .2);
+      this.scene.add(sp);
+      this.particles.push({ sp, life: 0, max: .28 + Math.random() * .25, vel: new THREE.Vector3((Math.random() - .5) * 8, Math.random() * 5 + 1, (Math.random() - .5) * 8), grow: .3, spark: true });
+    }
+  },
+  updateParticles(dt) {
+    for (let i = this.particles.length - 1; i >= 0; i--) {
+      const p = this.particles[i];
+      p.life += dt;
+      if (p.life >= p.max) { this.scene.remove(p.sp); p.sp.material.dispose(); this.particles.splice(i, 1); continue; }
+      p.sp.position.addScaledVector(p.vel, dt);
+      if (p.spark) { p.vel.y -= 12 * dt; p.sp.material.opacity = 1 - p.life / p.max; }
+      else { p.vel.multiplyScalar(1 - dt * 1.6); p.sp.scale.addScalar(dt * p.grow); p.sp.material.opacity = .42 * (1 - p.life / p.max); }
+    }
+    if (this.dust) {
+      this.dust.rotation.y += dt * .012;
+      this.dust.position.y = Math.sin(this.elapsed * .3) * .2;
+    }
+  },
+
+  updateCamera(dt, countdown) {
+    if (!this.player) return;
+    if (this.camMode === 'full') { this.updateCameraButtons(); return; }
+    const car = this.player;
+    const tan = this.curve.getTangentAt(car.t);
+    const fwd = new THREE.Vector3(tan.x, 0, tan.z).normalize();
+    const p = car.group.position;
+    let back = 6.4, height = 3.0, look = 4.2;
+    if (this.camMode === 'wide') { back = 13.5; height = 7.2; look = 7.5; }
+    if (this.camMode === 'chase') { back = 4.7; height = 1.85; look = 5.5; }
+    const target = p.clone().addScaledVector(fwd, -back).setY(p.y + height);
+    const lookTarget = p.clone().addScaledVector(fwd, look).setY(p.y + .95);
+    if (countdown) {
+      this.camPos.copy(target); this.camLook.copy(lookTarget);
+    } else {
+      const k = 1 - Math.exp(-dt * (this.camMode === 'chase' ? 11 : 7));
+      this.camPos.lerp(target, k);
+      this.camLook.lerp(lookTarget, 1 - Math.exp(-dt * 10));
+    }
+    this.shake = Math.max(0, this.shake - dt * 2.2);
+    const sx = (Math.random() - .5) * this.shake * 1.2;
+    const sy = (Math.random() - .5) * this.shake * 1.2;
+    this.camera.position.set(this.camPos.x + sx, Math.max(.4, this.camPos.y + sy), this.camPos.z);
+    this.camera.up.set(0, 1, 0);
+    this.camera.lookAt(this.camLook.x, this.camLook.y, this.camLook.z);
+    this.camera.fov = this.camMode === 'wide' ? 52 : this.camMode === 'chase' ? 64 : 58;
+    this.camera.updateProjectionMatrix();
+  },
+  updateCameraButtons() {
+    if (this._camBtnLoaded) return;
+    this._camBtnLoaded = true;
+    $$('.cam-btn').forEach(b => b.addEventListener('click', () => this.setCam(b.dataset.cam)));
+  },
+
+  updateHud(force) {
+    const curLapTime = this.started ? Math.max(0, this.elapsed - this.lapStart) : 0;
+    $('#raceTimer').textContent = fmtTime(curLapTime);
+    $('#raceLap').textContent = Math.min(this.player.lap, this.laps);
+    $('#raceLaps').textContent = this.laps;
+    $('#raceBest').textContent = 'Best ' + fmtTime(this.bestLap);
+    $('#raceCash').textContent = Math.round(S.cash).toLocaleString('en-US');
+    $('#racePos').textContent = this.pos;
+    const st = this.itemState;
+    let status = 'Ready';
+    if (st.boost > 0) status = 'BOOST'; else if (this.player && this.player.boost > 0) status = 'BOOST';
+    else if (this.player && this.player.oil > 0) status = 'OIL SLICK';
+    else if (Math.abs((this.player && this.player.drift) || 0) > .08) status = 'DRIFT';
+    else if (st.lastCoin) status = `+$${st.lastCoin} COIN`;
+    const el = $('#raceItemStatus');
+    if (el) { el.textContent = status; el.className = status === 'Ready' ? 'text-slate-300' : status === 'DRIFT' ? 'text-magentax' : status.includes('COIN') ? 'text-amber-300' : 'text-cyanx pulse-dot'; }
+    const now = performance.now();
+    if (force || now - this.lbTimer > 160) {
+      this.lbTimer = now;
+      const sorted = this.standings || this.cars.slice().sort((a, b) => b.dist - a.dist);
+      const sig = sorted.map(c => c.idx + (c.isPlayer ? 'P' : '')).join(',') + '|' + sorted.map(c => c.lap).join(',');
+      const wrap = $('#raceLeaderboard');
+      if (sig !== this.lastLb) {
+        this.lastLb = sig;
+        wrap.innerHTML = sorted.map((c, i) => {
+          const pos = i + 1;
+          const medal = pos === 1 ? '#c6ff3d' : pos === 2 ? '#cfd8e4' : pos === 3 ? '#e2a06a' : '#6f7a8c';
+          return `<div class="lb-item relative px-1.5 py-1 ${c.isPlayer ? '!border-lime/50' : ''}" data-lb="${c.idx}">
+            <div class="flex items-center gap-1.5">
+              <span class="font-display w-3 text-[9px] font-black" style="color:${medal}">${pos}</span>
+              <span class="h-1.5 w-1.5 shrink-0 rounded-full" style="background:${c.color}"></span>
+              <span class="min-w-0 flex-1 truncate text-[9.5px] font-bold ${c.isPlayer ? 'text-lime' : 'text-slate-200'}">${c.name}</span>
+              <span class="text-[8px] text-slate-500">L${Math.min(c.lap, this.laps)}</span>
+            </div>
+            <div class="mt-1 h-[3px] overflow-hidden rounded-full bg-white/10"><i class="block h-full rounded-full" style="width:${clamp((c.dist / (this.laps * this.trackLength)) * 100, 2, 100)}%;background:${c.color}"></i></div>
+          </div>`;
+        }).join('');
+      } else {
+        sorted.forEach(c => {
+          const row = wrap.querySelector(`[data-lb="${c.idx}"] i`);
+          if (row) row.style.width = clamp((c.dist / (this.laps * this.trackLength)) * 100, 2, 100) + '%';
+        });
+      }
+    }
+  },
+
+  flash(color) {
+    const f = $('#raceFlash');
+    if (!f) return;
+    f.style.transition = 'none'; f.style.background = color; f.style.opacity = '1';
+    requestAnimationFrame(() => { f.style.transition = 'opacity .45s'; f.style.opacity = '0'; });
+  },
+
+  togglePause(force) {
+    if (!this.active || this.finished) return;
+    this.paused = force !== undefined ? force : !this.paused;
+    const menu = $('#pauseMenu');
+    menu.classList.toggle('hidden', !this.paused);
+    menu.classList.toggle('flex', this.paused);
+    if (this.paused) { this.input.left = false; this.input.right = false; }
+  },
+
+  finishRace() {
+    if (this.finished) return;
+    this.finished = true;
+    this.player.finished = true;
+    const place = 1 + this.cars.filter(c => c !== this.player && c.dist > this.player.dist).length;
+    this.pos = place;
+    const result = this.applyRewards(place);
+    this.result = result;
+    this.updateHud(true);
+    if (place === 1) Sfx.win(); else Sfx.lose();
+    setTimeout(() => this.showResults(result), 750);
+  },
+
+  applyRewards(place) {
+    const wins = place === 1;
+    const rewards = [];
+    let cash = 0;
+    // stake
+    if (this.stake > 0) {
+      if (place === 1) { cash += this.stake * 2; rewards.push({ icon: '🏁', label: `1st place — stake doubled (${fmt$(this.stake * 2)})`, cls: 'text-lime' }); }
+      else if (place === 2) { cash += this.stake; rewards.push({ icon: '🥈', label: `2nd place — stake returned (${fmt$(this.stake)})`, cls: 'text-slate-200' }); }
+      else rewards.push({ icon: '💸', label: 'Stake lost', cls: 'text-rose-300' });
+    }
+    // base cash
+    const base = Math.round(rand(25, 140));
+    cash += base;
+    rewards.push({ icon: '💵', label: `Race purse +${fmt$(base)}`, cls: 'text-amber-300' });
+    let jackpot = false;
+    if (Math.random() < 1 / 15) { cash += 250; jackpot = true; rewards.push({ icon: '🎰', label: 'JACKPOT! +$250', cls: 'text-amber-300 font-black' }); Sfx.key(); }
+    // part drop on win
+    if (wins && Math.random() < 1 / 6) {
+      const owned = new Set(S.ownedParts);
+      const candidates = PARTS.filter(p => !owned.has(p.id));
+      if (candidates.length) {
+        const p = pick(candidates);
+        S.ownedParts.push(p.id);
+        rewards.push({ icon: p.icon, label: `Part drop: ${p.name} unlocked!`, cls: 'text-magentax' });
+        Sfx.key();
+      } else {
+        cash += 120;
+        rewards.push({ icon: '🧰', label: 'All parts owned — +$120 bonus', cls: 'text-amber-300' });
+      }
+    }
+    // boss key 1/400 any race
+    if (Math.random() < 1 / 400) {
+      S.bossKeys++;
+      rewards.push({ icon: '🗝️', label: 'RARE! Boss Key +1', cls: 'text-amber-300' });
+      Sfx.key();
+    }
+    // blue key boss only 1/800
+    const isBoss = this.storyCtx && this.storyCtx.type === 'boss';
+    if (isBoss && wins && Math.random() < 1 / 800) {
+      S.blueKeys++;
+      rewards.push({ icon: '🔹', label: 'ULTRA RARE! Blue Key +1', cls: 'text-sky-300' });
+      Sfx.key();
+    }
+    // story progression
+    if (this.storyCtx) {
+      const d = this.storyCtx.district;
+      if (this.storyCtx.type === 'guard' && wins) {
+        const cur = S.story.guards[d] || 0;
+        const max = DISTRICTS[d - 1].guards;
+        if (cur < max) {
+          S.story.guards[d] = cur + 1;
+          S.bossKeys++;
+          rewards.push({ icon: '🗝️', label: `Guard beaten! Boss Key +1 (${S.bossKeys})`, cls: 'text-amber-300' });
+        } else {
+          rewards.push({ icon: '✅', label: 'Guard rematch cleared', cls: 'text-slate-300' });
+        }
+      }
+      if (this.storyCtx.type === 'boss' && wins) {
+        if (!S.story.bosses.includes(d)) { S.story.bosses.push(d); S.story.bosses.sort(); }
+        rewards.push({ icon: '🏆', label: `District ${d} Boss defeated — trophy earned!`, cls: 'text-amber-300 font-black' });
+      }
+    }
+    S.story.races++;
+    if (wins) S.story.wins++;
+    S.cash += cash;
+    save(true);
+    return { place, cash, rewards, jackpot, win: wins, time: this.elapsed, best: this.bestLap, startPos: this.startPos, district: this.storyCtx && this.storyCtx.district };
+  },
+
+  showResults(r) {
+    $('#pauseMenu').classList.add('hidden'); $('#pauseMenu').classList.remove('flex');
+    $('#resultPlace').innerHTML = r.place + `<span class="text-lg text-slate-500">${ordinal(r.place)}</span>`;
+    const subs = ['', 'Flawless driving. The streets remember.', 'So close — the lead was right there.', 'A hard-earned podium step.', 'The pack got away. Again.'];
+    $('#resultSub').textContent = subs[r.place] || 'Race complete.';
+    $('#resultKicker').textContent = this.storyCtx ? (this.storyCtx.type === 'boss' ? 'BOSS BATTLE COMPLETE' : 'STORY QUALIFIER COMPLETE') : 'RACE COMPLETE';
+    $('#resultTime').textContent = fmtTime(r.time);
+    $('#resultBest').textContent = fmtTime(r.best);
+    $('#resultEarned').textContent = fmt$(r.cash);
+    $('#resultRewards').innerHTML = r.rewards.map(x => `<div class="flex items-center gap-2 rounded-lg border border-white/[.06] bg-white/[.025] px-2.5 py-1.5 text-[10.5px] ${x.cls || 'text-slate-300'}"><span>${x.icon}</span><span>${x.label}</span></div>`).join('');
+    const climb = $('#climbWrap');
+    if (r.place < r.startPos) {
+      climb.classList.remove('hidden');
+      const bars = [{ label: 'START', pos: r.startPos }, { label: 'FINISH', pos: r.place }];
+      $('#climbChart').innerHTML = bars.map(b => `<div class="flex flex-col items-center gap-1 h-full justify-end">
+        <div class="text-[9px] font-bold ${b.label === 'FINISH' ? 'text-lime' : 'text-slate-400'}">P${b.pos}</div>
+        <div class="bar-climb" style="height:${(5 - b.pos) / 4 * 56}px;${b.label === 'START' ? 'background:linear-gradient(180deg,#7b8799,#3e4654);' : ''}"></div>
+        <div class="text-[7.5px] uppercase tracking-widest text-slate-500">${b.label}</div>
+      </div>`).join('');
+    } else {
+      climb.classList.add('hidden');
+    }
+    const storyBtn = $('#resultsStoryBtn');
+    if (this.storyCtx) storyBtn.classList.remove('hidden'); else storyBtn.classList.add('hidden');
+    const bp = $('#bossProgress');
+    if (this.storyCtx) {
+      bp.classList.remove('hidden');
+      const d = this.storyCtx.district;
+      const dist = DISTRICTS[d - 1];
+      if (this.storyCtx.type === 'guard') {
+        const done = S.story.guards[d] || 0;
+        bp.textContent = done >= dist.guards ? `All ${dist.guards} guards cleared. The ${dist.bossName} awaits.` : `${done} / ${dist.guards} guards beaten · collect 4 Boss Keys to challenge ${dist.bossName}.`;
+      } else {
+        bp.textContent = r.place === 1 ? `🏆 ${dist.bossName} defeated!` : `The ${dist.bossName} escaped. Replay when you're ready.`;
+      }
+    } else bp.classList.add('hidden');
+    $('#raceAgainBtn').onclick = () => this.start(this.opts);
+    $('#resultsMenuBtn').onclick = () => this.quit();
+    storyBtn.onclick = () => { this.quit(true); };
+    $('#raceResults').classList.remove('hidden');
+    this.updateHud(true);
+  },
+
+  quit(returnStory) {
+    this.active = false; this.finished = false; this.paused = false;
+    $('#raceOverlay').classList.add('hidden');
+    $('#raceResults').classList.add('hidden');
+    document.body.style.overflow = '';
+    this.input.left = this.input.right = false;
+    if (this.dust) this.dust = null;
+    if (returnStory || this.mode === 'story') {
+      setTab('story');
+      if (returnStory) Hub.open();
+      renderStoryPage();
+    }
+    save();
+  },
+
+
+
+
 </script>
 </body>
