const bindSteer = (el, side) => {
  if (!el) return;
  const on = (e) => { e.preventDefault(); e.stopPropagation(); Race.input[side] = true; el.classList.add('pressed'); };
  const off = (e) => { if (e) e.preventDefault(); Race.input[side] = false; el.classList.remove('pressed'); };
  el.addEventListener('pointerdown', on);
  el.addEventListener('pointerup', off);
  el.addEventListener('pointercancel', off);
  el.addEventListener('pointerleave', off);
  el.addEventListener('touchstart', (e) => { e.preventDefault(); on(e); }, { passive: false });
  el.addEventListener('touchend', (e) => { e.preventDefault(); off(e); }, { passive: false });
};
bindSteer($('#steerLeft'), 'left');
bindSteer($('#steerRight'), 'right');
