  if (Race.active) {
    if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', ' '].includes(e.key)) e.preventDefault();
    if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') Race.input.left = true;
    if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') Race.input.right = true;
    if (e.key === 'Escape' || e.key === 'p' || e.key === 'P') { e.preventDefault(); Race.togglePause(); }
    if (e.key === 'c' || e.key === 'C') cycleCam();
    if (e.key === 'r' || e.key === 'R') { if (!Race.finished && Race.paused) Race.start(Race.opts); }
  }
});
window.addEventListener('keyup', (e) => {
  if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') Race.input.left = false;
  if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') Race.input.right = false;
});

/* ============================================================
   STORY MODE
   ============================================================ */
function guardCount(d) { return S.story.guards[d] || 0; }
function bossReq(d) {
  const dist = DISTRICTS[d - 1];
  const req = dist.req;
  const missing = [];
  if (guardCount(d) < dist.guards) missing.push({ label: `${guardCount(d)}/${dist.guards} guards`, ok: false });
  if (S.bossKeys < 4) missing.push({ label: `${S.bossKeys}/4 Boss Keys`, ok: false });
  if (req.engine && S.upgrades.engine < req.engine) missing.push({ label: `Engine Lv.${req.engine}`, ok: false });
  if (req.handling && S.upgrades.handling < req.handling) missing.push({ label: `Handling Lv.${req.handling}`, ok: false });
  if (req.aero && S.upgrades.aero < req.aero) missing.push({ label: `Aero Lv.${req.aero}`, ok: false });
  if (req.wins && S.story.wins < req.wins) missing.push({ label: `${req.wins} race wins`, ok: false });
  return { ok: missing.length === 0, missing };
}
function startGuardRace(d, fromHub) {
  const dist = DISTRICTS[d - 1];
  Sfx.resume();
  Hub.close();
  Race.start({ laps: 1, mode: 'story', stake: 0, terrain: dist.terrain, time: d >= 3 ? 'night' : d === 2 ? 'sunset' : 'day', story: { type: 'guard', district: d }, trackName: `${dist.name} — Guard` });
}
function startBossRace(d) {
  const dist = DISTRICTS[d - 1];
  const chk = bossReq(d);
  if (!chk.ok) {
    modal(`Challenge ${dist.bossName}`, `You are not ready yet:<br><br>` + chk.missing.map(m => `<div class="flex items-center gap-2 text-[11.5px] text-rose-300">✕ ${m.label}</div>`).join('') + `<br><span class="text-[10.5px] text-slate-500">Win guard races, buy upgrades and collect Boss Keys.</span>`, 'OK', () => {});
    return;
  }
  Sfx.resume();
  Hub.close();
  Race.start({ laps: dist.bossLaps, mode: 'story', stake: 0, terrain: dist.terrain, time: d >= 3 ? 'night' : 'sunset', story: { type: 'boss', district: d }, trackName: `${dist.name} — Boss` });
}

