/* ---------------- CITY HUB ---------------- */
const Hub = {
  active: false, canvas: null, ctx: null, W: 0, H: 0,
  car: { x: 0, z: 0, vx: 0, vz: 0, angle: 0 },
  keys: {}, stick: { x: 0, z: 0, active: false },
  city: null, gates: [], nearGate: null, t: 0, bound: { x: 760, z: 560 }, boundFn: null,
  init() {
    if (this.canvas) return;
    this.canvas = $('#hubCanvas');
    this.ctx = this.canvas.getContext('2d');
    this.genCity();
    const stickEl = $('#hubJoystick'), knob = $('#hubStick');
    if (stickEl) {
      const move = (e) => {
        const rect = stickEl.getBoundingClientRect();
        const cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;
        const dx = e.clientX - cx, dy = e.clientY - cy;
        const len = Math.hypot(dx, dy) || 1;
        const max = rect.width / 2 - 14;
        const cl = Math.min(len, max);
        this.stick.x = dx / len * cl / max;
        this.stick.z = dy / len * cl / max;
        this.stick.active = true;
        knob.style.transform = `translate(calc(-50% + ${this.stick.x * max}px), calc(-50% + ${this.stick.z * max}px))`;
      };
      const end = () => { this.stick.x = 0; this.stick.z = 0; this.stick.active = false; knob.style.transform = 'translate(-50%,-50%)'; };
      stickEl.addEventListener('pointerdown', (e) => { e.preventDefault(); stickEl.setPointerCapture(e.pointerId); move(e); });
      stickEl.addEventListener('pointermove', (e) => { if (this.stick.active) move(e); });
      stickEl.addEventListener('pointerup', end); stickEl.addEventListener('pointercancel', end);
    }
    $('#hubBackBtn').addEventListener('click', () => this.close());
    $('#gateEnterBtn').addEventListener('click', () => { if (this.nearGate) this.enterGate(this.nearGate.id); });
    window.addEventListener('keydown', (e) => {
      this.keys[e.key.toLowerCase()] = true;
      if (e.key === 'Escape' && this.active) this.close();
      if ((e.key === 'e' || e.key === 'E') && this.active && this.nearGate) this.enterGate(this.nearGate.id);
      if (this.active && ['arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(e.key.toLowerCase())) e.preventDefault();
    });
    window.addEventListener('keyup', (e) => { this.keys[e.key.toLowerCase()] = false; });
    if (window.ResizeObserver) new ResizeObserver(() => this.resize()).observe($('#hubCanvas'));
  },
  genCity() {
    const rng = mulberry32(987123);
    const buildings = [];
    const parks = [];
    for (let gx = -3; gx <= 3; gx++) for (let gz = -2; gz <= 2; gz++) {
      const bx = gx * 250, bz = gz * 210;
      const bw = 180, bh = 150;
      const isPark = (gx === -1 && gz === 1) || (gx === 2 && gz === -1);
      if (isPark) { parks.push({ x: bx - bw / 2, z: bz - bh / 2, w: bw, h: bh }); continue; }
      if (Math.abs(gx) < 1 && Math.abs(gz) < 1) continue;
      const n = 1 + Math.floor(rng() * 3);
      for (let i = 0; i < n; i++) {
        const w = 46 + rng() * 48, h = 42 + rng() * 46;
        const x = bx - bw / 2 + 10 + rng() * Math.max(4, bw - w - 20);
        const z = bz - bh / 2 + 10 + rng() * Math.max(4, bh - h - 20);
        buildings.push({ x, z, w, h, hue: .56 + rng() * .08, lit: rng() > .35, tall: 4 + Math.floor(rng() * 12) });
      }
    }
    this.city = { buildings, parks };
    this.gates = [
      { id: 1, x: -610, z: -400, color: '#c6ff3d', name: DISTRICTS[0].name },
      { id: 2, x: 610, z: -400, color: '#39e7ff', name: DISTRICTS[1].name },
      { id: 3, x: -610, z: 410, color: '#ff4fd8', name: DISTRICTS[2].name },
      { id: 4, x: 610, z: 410, color: '#ffd24f', name: DISTRICTS[3].name },
    ];
    this.props = [
      { x: -300, z: -260, type: 'sneaker' }, { x: 330, z: 240, type: 'can' },
      { x: 300, z: -230, type: 'pencil' }, { x: -360, z: 250, type: 'coin' },
    ];
  },
  open(focusDistrict) {
    this.init();
    this.active = true;
    $('#storyOverlay').classList.remove('hidden');
    document.body.style.overflow = 'hidden';
    this.resize();
    Sfx.resume();
    if (focusDistrict) {
      const g = this.gates.find(g => g.id === focusDistrict);
      if (g) { this.car.x = g.x * .55; this.car.z = g.z * .55; this.car.angle = Math.atan2(-g.x, -g.z); }
    }
    this.lastT = performance.now();
    setTimeout(() => { if (this.active) toast('Drag the joystick or use WASD to drive to a District Gate', 'info'); }, 500);
  },
  close() {
    this.active = false;
    $('#storyOverlay').classList.add('hidden');
    document.body.style.overflow = '';
    renderStoryPage();
    updateCurrencyHud();
  },
  enterGate(id) {
    this.close();
    setTab('story');
    const d = DISTRICTS[id - 1];
    toast(`🗺️ ${d.name} — ${d.guards} guards await`, 'good');
    setTimeout(() => {
      const card = document.getElementById('district-card-' + id);
      if (card) card.scrollIntoView({ behavior: 'smooth', block: 'center' });
      if (card) {
        card.style.boxShadow = '0 0 0 2px ' + d.accent + ', 0 0 32px rgba(198,255,61,.35)';
        setTimeout(() => card.style.boxShadow = '', 2200);
      }
    }, 260);
  },
  resize() {
    if (!this.canvas) return;
    const W = this.canvas.clientWidth || window.innerWidth;
    const H = this.canvas.clientHeight || window.innerHeight;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.W = W; this.H = H;
    if (this.canvas.width !== Math.round(W * dpr) || this.canvas.height !== Math.round(H * dpr)) {
      this.canvas.width = Math.round(W * dpr); this.canvas.height = Math.round(H * dpr);
    }
  },
  tick(dt) {
    if (!this.active) return;
    this.t += dt;
    this.resize();
    const c = this.car;
    let ix = 0, iz = 0;
    if (this.keys['a'] || this.keys['arrowleft']) ix -= 1;
    if (this.keys['d'] || this.keys['arrowright']) ix += 1;
    if (this.keys['w'] || this.keys['arrowup']) iz -= 1;
    if (this.keys['s'] || this.keys['arrowdown']) iz += 1;
    ix += this.stick.x; iz += this.stick.z;
    const len = Math.hypot(ix, iz);
    if (len > 1) { ix /= len; iz /= len; }
    const speed = 320;
    c.vx = lerp(c.vx, ix * speed, Math.min(1, dt * 6));
    c.vz = lerp(c.vz, iz * speed, Math.min(1, dt * 6));
    if (len > .1) {
      const targetAngle = Math.atan2(c.vx, c.vz);
      let da = targetAngle - c.angle;
      while (da > Math.PI) da -= Math.PI * 2;
      while (da < -Math.PI) da += Math.PI * 2;
      c.angle += da * Math.min(1, dt * 8);
    }
    c.x += c.vx * dt; c.z += c.vz * dt;
    // collide with buildings
    const R = 26;
    for (const b of this.city.buildings) {
      const cx = clamp(c.x, b.x, b.x + b.w), cz = clamp(c.z, b.z, b.z + b.h);
      const dx = c.x - cx, dz = c.z - cz;
      const d2 = dx * dx + dz * dz;
      if (d2 < R * R) {
        const d = Math.sqrt(d2) || .001;
        const push = (R - d) + .01;
        if (d2 > .001) { c.x += dx / d * push; c.z += dz / d * push; }
        else { c.x += push; }
        c.vx *= .5; c.vz *= .5;
      }
    }
    c.x = clamp(c.x, -this.bound.x, this.bound.x);
    c.z = clamp(c.z, -this.bound.z, this.bound.z);
    // gate proximity
    let near = null, best = 120;
    for (const g of this.gates) {
      const d = Math.hypot(c.x - g.x, c.z - g.z);
      if (d < best) { best = d; near = g; }
    }
    this.nearGate = near;
    const prompt = $('#gatePrompt');
    if (near) {
      prompt.style.opacity = '1';
      $('#gatePromptNum').textContent = near.id;
      $('#gatePromptTitle').textContent = `District ${near.id} · ${near.name}`;
      $('#gatePromptSub').textContent = `${DISTRICTS[near.id - 1].guards} guards · ${S.story.bosses.includes(near.id) ? 'Champion defeated' : 'Boss awaits'}`;
      $('#gatePromptNum').style.background = near.color;
    } else prompt.style.opacity = '0';
    $('#hubCash').textContent = Math.round(S.cash).toLocaleString('en-US');
    this.draw();
  },
  worldToScreen(x, z) {
    const scale = this.scale;
    return [this.W / 2 + (x - this.car.x) * scale, this.H / 2 + (z - this.car.z) * scale];
  },
  draw() {
    const ctx = this.ctx, W = this.W, H = this.H;
    if (!ctx) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.scale = clamp(Math.min(W, H) / 850, .52, .95);
    const s = this.scale;
    ctx.fillStyle = '#101319'; ctx.fillRect(0, 0, W, H);
    // ground grid / sidewalks
    ctx.save();
    ctx.translate(W / 2, H / 2); ctx.scale(s, s); ctx.translate(-this.car.x, -this.car.z);
    // city blocks base
    ctx.fillStyle = '#171b22'; ctx.fillRect(-this.bound.x - 80, -this.bound.z - 80, (this.bound.x + 80) * 2, (this.bound.z + 80) * 2);
    // roads
    ctx.strokeStyle = '#292e37'; ctx.lineWidth = 92;
    for (let gx = -3; gx <= 3; gx++) { ctx.beginPath(); ctx.moveTo(gx * 250, -this.bound.z - 60); ctx.lineTo(gx * 250, this.bound.z + 60); ctx.stroke(); }
    for (let gz = -2; gz <= 2; gz++) { ctx.beginPath(); ctx.moveTo(-this.bound.x - 60, gz * 210); ctx.lineTo(this.bound.x + 60, gz * 210); ctx.stroke(); }
    ctx.strokeStyle = '#383f4b'; ctx.lineWidth = 5;
    for (let gx = -3; gx <= 3; gx++) { ctx.beginPath(); ctx.moveTo(gx * 250, -this.bound.z - 60); ctx.lineTo(gx * 250, this.bound.z + 60); ctx.stroke(); }
    for (let gz = -2; gz <= 2; gz++) { ctx.beginPath(); ctx.moveTo(-this.bound.x - 60, gz * 210); ctx.lineTo(this.bound.x + 60, gz * 210); ctx.stroke(); }
    // lane dashes
    ctx.strokeStyle = 'rgba(255,255,255,.22)'; ctx.lineWidth = 3; ctx.setLineDash([22, 26]);
    for (let gx = -3; gx <= 3; gx++) { ctx.beginPath(); ctx.moveTo(gx * 250, -this.bound.z - 60); ctx.lineTo(gx * 250, this.bound.z + 60); ctx.stroke(); }
    for (let gz = -2; gz <= 2; gz++) { ctx.beginPath(); ctx.moveTo(-this.bound.x - 60, gz * 210); ctx.lineTo(this.bound.x + 60, gz * 210); ctx.stroke(); }
    ctx.setLineDash([]);
    // crosswalks
    for (let gx = -3; gx <= 3; gx++) for (let gz = -2; gz <= 2; gz++) {
      ctx.fillStyle = 'rgba(240,245,250,.3)';
      for (let i = 0; i < 7; i++) { ctx.fillRect(gx * 250 - 38 + i * 12, gz * 210 + 50, 7, 22); ctx.fillRect(gx * 250 - 38 + i * 12, gz * 210 - 72, 7, 22); }
    }
    // blocks (sidewalks)
    for (let gx = -3; gx <= 3; gx++) for (let gz = -2; gz <= 2; gz++) {
      ctx.fillStyle = '#20252d'; ctx.fillRect(gx * 250 - 90, gz * 210 - 75, 180, 150);
      ctx.strokeStyle = 'rgba(255,255,255,.05)'; ctx.lineWidth = 2; ctx.strokeRect(gx * 250 - 90, gz * 210 - 75, 180, 150);
    }
    // parks
    for (const p of this.city.parks) {
      ctx.fillStyle = '#234a33'; roundRectPath(ctx, p.x, p.z, p.w, p.h, 12); ctx.fill();
      ctx.fillStyle = 'rgba(198,255,61,.5)';
      const rng = mulberry32(p.x * 13 + p.z * 7);
      for (let i = 0; i < 18; i++) { ctx.beginPath(); ctx.arc(p.x + 12 + rng() * (p.w - 24), p.z + 12 + rng() * (p.h - 24), 3 + rng() * 4, 0, 7); ctx.fill(); }
    }
    // buildings
    for (const b of this.city.buildings) {
      ctx.fillStyle = 'rgba(0,0,0,.5)'; ctx.fillRect(b.x + 10, b.z + 12, b.w, b.h);
      ctx.fillStyle = `hsl(${b.hue * 360},9%,${24 + b.tall}%)`;
      roundRectPath(ctx, b.x, b.z, b.w, b.h, 5); ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,.1)'; ctx.lineWidth = 1.5; ctx.stroke();
      // windows
      for (let wy = 8; wy < b.h - 8; wy += 16) for (let wx = 8; wx < b.w - 8; wx += 15) {
        if ((wx * 7 + wy * 13 + b.tall) % 5 > 1) {
          ctx.fillStyle = b.lit ? 'rgba(255,216,138,.32)' : 'rgba(80,90,105,.3)';
          ctx.fillRect(b.x + wx, b.z + wy, 7, 5);
        }
      }
      // rooftop detail
      ctx.fillStyle = 'rgba(255,255,255,.06)'; ctx.fillRect(b.x + b.w * .2, b.z + b.h * .3, b.w * .3, b.h * .2);
    }
    // giant props
    for (const p of this.props) {
      ctx.save(); ctx.translate(p.x, p.z);
      if (p.type === 'sneaker') {
        ctx.fillStyle = '#d8dde6'; ctx.beginPath(); ctx.ellipse(0, 0, 55, 26, .2, 0, 7); ctx.fill();
        ctx.fillStyle = '#ff5b5b'; ctx.fillRect(-45, -6, 70, 9);
