      ctx.restore();
    }
    // gates
    for (const g of this.gates) {
      const pulse = .5 + Math.sin(this.t * 2 + g.id) * .5;
      ctx.save(); ctx.translate(g.x, g.z);
      const grd = ctx.createRadialGradient(0, 0, 8, 0, 0, 78);
      grd.addColorStop(0, 'rgba(0,0,0,0)'); grd.addColorStop(.7, g.color + '33'); grd.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = grd; ctx.beginPath(); ctx.arc(0, 0, 78, 0, 7); ctx.fill();
      ctx.strokeStyle = g.color; ctx.lineWidth = 4; ctx.globalAlpha = .5 + pulse * .5;
      ctx.beginPath(); ctx.arc(0, 0, 62 + pulse * 4, 0, 7); ctx.stroke();
      ctx.globalAlpha = 1;
      ctx.beginPath(); ctx.arc(0, 0, 54, 0, 7); ctx.fillStyle = 'rgba(10,14,20,.85)'; ctx.fill();
      ctx.fillStyle = g.color; ctx.font = '900 38px Orbitron, sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
