    ctx.fillStyle = lg; ctx.beginPath(); ctx.moveTo(-11, -16); ctx.lineTo(-54, -150); ctx.lineTo(54, -150); ctx.lineTo(11, -16); ctx.closePath(); ctx.fill();
    const pcol = getPaint();
    ctx.fillStyle = pcol.css; roundRectPath(ctx, -17, -26, 34, 52, 8); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.25)'; roundRectPath(ctx, -13, -20, 26, 18, 5); ctx.fill();
    ctx.fillStyle = '#0c1018'; roundRectPath(ctx, -11, 4, 22, 16, 4); ctx.fill();
