    ctx.fillStyle = v; ctx.fillRect(0, 0, W, H);
    // district compass labels at edges
    ctx.font = '700 9px Inter, sans-serif'; ctx.fillStyle = 'rgba(255,255,255,.35)'; ctx.textAlign = 'left';
    ctx.fillText('THE UNSEEN STREETS · CITY HUB', 16, H - 18);
  }
};

/* ---------------- INIT ---------------- */
function initAll() {
  renderPaint(); renderModels(); renderWheels(); renderParts(); renderUpgrades(); renderGarage(); renderTrackQuickList(); renderStoryPage();
  updateStatsUI(); updateCurrencyHud();
  showroom.init();
  showroom.updateSpinBtn();
  const savedTab = 'customize';
  setTab(savedTab);
  $('#raceSoundBtn').textContent = S.sound ? '🔊 On' : '🔇 Muted';
  window.addEventListener('resize', () => {
    if (activeTab === 'track') drawTrackCanvas();
    if (activeTab === 'customize') showroom.resize();
    if (Hub.active) Hub.resize();
  });
  // keyboard shortcut for tabs
  window.addEventListener('keydown', (e) => {
    if (Race.active || Hub.active) return;
    if (e.target && /INPUT|TEXTAREA|SELECT/.test(e.target.tagName)) return;
    if (e.key === '1') setTab('customize');
    if (e.key === '2') setTab('track');
    if (e.key === '3') setTab('story');
  });
  if (S.sound) Sfx.resume();
}
document.addEventListener('pointerdown', () => Sfx.resume(), { once: true });
try { initAll(); } catch (err) {
  console.error(err);
  const t = document.createElement('div');
  t.className = 'fixed inset-0 z-[100] grid place-items-center bg-black p-6 text-center text-sm text-rose-300';
  t.textContent = 'Failed to initialize: ' + err.message;
  document.body.appendChild(t);
}
</script>

