function makeSampleOval() {
  const g = emptyGrid();
  const put = (x, y, part, rot = 0) => { if (x >= 0 && x < 8 && y >= 0 && y < 5) g[y][x] = { part, rot }; };
  // start on the bottom straight
  put(1, 3, 'start', 0);
  put(2, 3, 'straight', 0); put(3, 3, 'straight', 0); put(4, 3, 'straight', 0); put(5, 3, 'straight', 0); put(6, 3, 'straight', 0);
  put(6, 2, 'curve', 0);
  put(6, 1, 'straight', 1); put(6, 0, 'curve', 1);
  put(5, 0, 'straight', 0); put(4, 0, 'straight', 0); put(3, 0, 'straight', 0); put(2, 0, 'straight', 0); put(1, 0, 'curve', 2);
  put(1, 1, 'straight', 1); put(1, 2, 'curve', 3);
  return g;
}
function makeBridgePreset() {
  const g = makeSampleOval();
  g[1][3] = { part: 'jump', rot: 0 };
  g[1][4] = { part: 'bridge', rot: 1 };
  g[2][5] = { part: 'loop', rot: 0 };
  return g;
}

